/* DAWAH X — ahmad, অধ্যায় 68 · খণ্ড 68 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][68]=[[13401,13401,"","তিনি বলেছিলেন যে, তিনি যেন মারা যান ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏قَالَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا ‏ ‏وَيْحَكَ ‏","","",""],[13402,13402,"","আমরা একটি প্রথা এবং একটি প্রচেষ্টা একটি প্রথা মধ্যে গ্রহণ যে একটি প্রথা গ্রহণ করা হয়েছে যে, একটি প্রথা জন্য যে প্রচেষ্টা তিনি প্রার্থনা আছে. আমি অন্ধ হয়ে যাব, তাকে বিশ্বাস করবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَلَدِهِ وَوَالِدِهِ وَالنَّاسِ أَجْمَعِينَ ‏","","",""],[13403,13403,"","আমরা একটি প্রথা এবং একটি প্রচেষ্টা একটি প্রথা মধ্যে গ্রহণ যে একটি প্রথা গ্রহণ করা হয়েছে যে প্রচেষ্টা, যে প্রচেষ্টা আমাকে এমন এক প্রথার দিকে নিয়ে যায় যা তার জন্য প্রার্থনা করে। আপনার টাকা তার জন্য প্রার্থনা করে এবং তিনি তার জন্য তার নিজের তিনজনকে আত্মসমর্পণ করো, আমি এটা পছন্দ করি না হয় আমি এটা রক্ষা করতাম, সে এটা থেকে রক্ষা পাওয়ার পর।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ طَعْمَ الْإِيمَانِ مَنْ كَانَ يُحِبُّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلَّهِ عَزَّ وَجَلَّ وَمَنْ كَانَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَمَنْ كَانَ أَنْ يُلْقَى فِي النَّارِ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَرْجِعَ فِي الْكُفْرِ بَعْدَ إِذْ أَنْقَذَهُ اللَّهُ مِنْهُ ‏","","",""],[13404,13404,"","আমরা একটা রীতি তৈরি করেছি... ...আর কথা বলার জন্য আমাকে কথা বলার জন্য একটা উপায় বের করতে হবে. আমি তাদেরকে তৈরি করতে অথবা বিছানায় যেতে দিতে চাই । ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَنْصَارَ ‏ ‏فَقَالَ أَفِيكُمْ أَحَدٌ مِنْ غَيْرِكُمْ فَقَالُوا لَا إِلَّا ‏ ‏ابْنُ أُخْتٍ لَنَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏مِنْ أَنْفُسِهِمْ ‏ ‏فَقَالَ إِنَّ ‏ ‏قُرَيْشًا ‏ ‏حَدِيثُ ‏ ‏عَهْدٍ ‏ ‏بِجَاهِلِيَّةٍ وَمُصِيبَةٍ وَإِنِّي أَرَدْتُ أَنْ ‏ ‏أُجِيزَهُمْ ‏ ‏وَأَتَأَلَّفَهُمْ ‏ ‏أَمَا تَرْضَوْنَ أَنْ يَرْجِعَ النَّاسُ بِالدُّنْيَا وَتَرْجِعُونَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى بُيُوتِكُمْ لَوْ سَلَكَ النَّاسُ وَادِيًا وَسَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏شِعْبًا ‏ ‏لَسَلَكْتُ ‏ ‏شِعْبَ ‏ ‏الْأَنْصَارِ ‏","","",""],[13405,13405,"","আমরা একটি প্রথা এবং একটি প্রচেষ্টা একটি প্রথা মধ্যে একটি প্রথা গ্রহণ যে প্রচেষ্টা সম্পর্কে বলেন যে ধনাত্মক প্রচেষ্টা আমাকে একটি প্রথা জন্য করেছি যে ধনাত্মক. আপনার টাকা আমরা এই কল্পনাতে আমরা শুরু করেছি. তুমি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ فِي هَذِهِ الْآيَةِ ‏ { ‏إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا ‏} ‏قَالَ ‏ ‏الْحُدَيْبِيَةُ ‏","","",""],[13406,13406,"","আমরা একে অপরের সমস্যার কথা বলেছি, যাতে তারা এটা স্পর্শ করতে পারে। আমার বাবা মনে করেন তারা ঈশ্বরের জন্য সুখী হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَلْفَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏فَكَانُوا ‏ ‏لَا يَجْهَرُونَ بِ ‏ { ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏}","","",""],[13407,13407,"","আমরা একটি প্রথা এবং একটি প্রথা গ্রহণ একটি প্রচেষ্টা সম্পর্কে কথা বলেছি যে একটি প্রথা মধ্যে একটি প্রথা গ্রহণ করা হয়েছে যে, আপনি যে অর্থ বলেন. আমি ঈশ্বরকে জিজ্ঞাসা করতে চাই এবং তারা তা করতে চান তার কাছে তালাক আছে, সে একজন শপথকারী মানুষের ইতিহাস পেয়েছে, তার জন্য প্রার্থনা করছে আর আমরা তার আত্মা উৎসর্গ করেছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَرَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَكْتُبَ إِلَى ‏ ‏الرُّومِ ‏ ‏كِتَابًا قَالُوا ‏ ‏إِنَّهُمْ لَا يَقْرَءُونَ كِتَابًا إِلَّا مَخْتُومًا قَالَ فَاتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا مِنْ فِضَّةٍ كَأَنِّي أَنْظُرُ إِلَى بَيَاضِهِ فِي يَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَقْشُهُ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏","","",""],[13408,13408,"","আমরা একটি আবেগ কথা বলেছি যে আমরা দু বার অক্সিজেনের শব্দ শোনার চেষ্টা করেছি এবং দু বার চেষ্টা করেছি। লর্ড প্রার্থনা করলেন এবং আত্মসমর্পণের জন্য আমাকে সাহায্য করার জন্য এবং আমাদের সাথে থাকার জন্য। আমি তার কাছে প্রার্থনা করা ভুলেই গিয়েছিলাম আর তাকে একটা কথা বলবো যে সে একটা ছেলে যে তার প্রাণ থেকে বেঁচে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَهْرَمُ ‏ ‏ابْنُ ‏ ‏آدَمَ ‏ ‏وَتَبْقَى مِنْهُ اثْنَتَانِ الْحِرْصُ وَالْأَمَلُ ‏","","",""],[13409,13409,"","আমরা একটা কথা বলেছি যে আমরা দু'বার একটা শব্দ শুনেছি যা আমি একবার শুনেছি। আমি বললাম, চাঁদটা তাঁর কাছে প্রার্থনা করে এসেছে এবং আমি তাকে উদ্ধার করেছি। দু'জন অভিজাত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجُ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏انْشَقَّ ‏ ‏الْقَمَرُ عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِرْقَتَيْنِ ‏","","",""],[13410,13410,"","আমরা শুনেছি যে লোকেরা তার কল্পনার পরিণতি বলে থাকে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏سَمِعَ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏انْشَقَّ ‏ ‏الْقَمَرُ عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13411,13411,"","আমরা একটা রীতি আর প্রচেষ্টা নিয়ে কথা বলেছি যা আমাকে এমন একটা রীতিতে নিয়ে এসেছে যা আমার কাছে এসেছে যা শোনা হয়েছে। তোমার ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমাদের উদ্ধার করেছেন। কথোপকথন এবং আমাদের অনেকের জন্য ভয় এবং ভয় যে আমাদের হত্যা করার চেষ্টা করেছে, সে তাকে জিজ্ঞেস করেছে এবং আদ্দি বলেছি সে ভালো যেতে না বলে। যখন কথা বলা হত, তখন এটা একটা বাজির মাধ্যমে বাপ্তাইজিত হয়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَهِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَلَا فَأْلَ قَالَ قِيلَ وَمَا الْفَأْلُ قَالَ الْكَلِمَةُ الطَّيِّبَةُ ‏ ‏وَاللَّفْظُ ‏ ‏لِمُحَمَّدِ بْنِ جَعْفَرٍ ‏","","",""],[13412,13412,"","আমরা আমাদের জনগণের হত্যার কথা বলেছি, টাকা ভুলে গিয়ে সে তাদের কাছে বলবে, শেষ জীবিত আছে আর বলছে সবচেয়ে খারাপটা নয় ভয় পাওয়ার জন্য, জয় আর ব্যথাই হচ্ছে সেই আক্রমন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنَّ الْعَيْشَ عَيْشُ ‏ ‏الْآخِرَهْ وَقَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ ‏ ‏اللَّهُمَّ لَا عَيْشَ إِلَّا عَيْشُ ‏ ‏الْآخِرَهْ ‏ ‏فَأَكْرِمْ ‏ ‏الْأَنْصَارَ ‏ ‏وَالْمُهَاجِرَهْ ‏","","",""],[13413,13413,"","আমরা একটি প্রথা তৈরি করা একটি কামনা সম্পর্কে কথা বলেছি এবং একটি প্রয়োজন আমাকে নিষ্ঠুরতা প্রথা দ্বারা পরিচালিত হয়েছে, বাবা, আমরা ইতিমধ্যে কথা বলেছি যে কিভাবে আমি মানুষের বিচার করতে পারি ঈশ্বরের জন্য প্রার্থনা করা, তাঁর ওপর বিশ্বাস রাখা হয়তো সবচেয়ে জঘন্য হত্যাকাণ্ডে বিশ্বাস করা যায় যে, তাঁর বন্ধুত্ব রয়েছে এবং এটা আমাদের জন্য হুমকি স্বরূপ ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِلَحْمٍ فَقِيلَ لَهُ إِنَّهُ قَدْ تُصُدِّقَ بِهِ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏فَقَالَ ‏ ‏هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَهُوَ لَنَا هَدِيَّةٌ ‏","","",""],[13414,13414,"","আমরা কথা বলেছি ঘোড়াকে লড়াইয়ের একটা উপায় খুঁজে বের করার জন্য। ভগবান তার কাছে প্রার্থনা করে আত্মসমর্পণ করে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏بَرِيرَةَ ‏ ‏تُصُدِّقَ عَلَيْهَا ‏ ‏بِصَدَقَةٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَلَنَا هَدِيَّةٌ ‏","","",""],[13415,13415,"","আমরা একটি প্রথা নিয়ে কথা বলেছি যে একটি প্রথা নিয়ে আমি একটি প্রথা তৈরি করেছি যে আমাকে তিনি আমার সাথে যুদ্ধ করতে এসেছিলেন তার কাছে প্রার্থনা এবং তাকে জিজ্ঞাসা যখন তিনি বললেন তিনি যেতে যাচ্ছে মেরে ফেলো, সে বলেছে তুমি আমার প্রেমে পড়েছো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَعْرَابِيٌّ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَتَى السَّاعَةُ قَالَ وَمَا أَعْدَدْتَ لَهَا قَالَ حُبَّ اللَّهِ وَرَسُولِهِ قَالَ أَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[13416,13416,"","আমরা একটি আবেগ কথা বলেছি যে শুনানির রীতি নিয়ে... ...যার মৃত্যু হয়েছে তাকে মেরে ফেলার ফলে... একজন নিহত মানুষের মৃত্যুর পর যে খুন হয়েছে তাকে হত্যা করা হয়েছে সে নিহত হয়েছে। যে লোক মানুষকে হত ্ যা করে , সে যেন দেখে তার সাথী হয় । যে লোক পুরুষ ও নারী মুমিন অবস ্ থায়ই একজন মানুষ আছে , তার জন ্ য সে একজন মানুষ বৈ তো নয় । যে লোক মানুষ জ ্ লোক আছে , সে একজন মানুষ বৈ নয় । একজন মানুষ হিসেবে সে একজন মানুষ যে মানুষ ছিল... ...যে একজন ঈশ্বর হিসেবে তার মাকে আমার ছেলের কাছে আত্মসমর্পণ করতে নির্দেশ দিয়েছেন, আর আমি হতে পারি। মনে আছে, তার মা তার জীবনের সবচেয়ে ভালো কিছু করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ نَبِيٍّ إِلَّا وَقَدْ أَنْذَرَ أُمَّتَهُ الْأَعْوَرَ الْكَافِرَ أَلَا إِنَّهُ أَعْوَرُ وَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ ‏ ‏ك ‏ ‏ف ‏ ‏ر ‏","","",""],[13417,13417,"","আমরা আবেগ নিয়ে কথা বলেছি... ...আমরা দুই বার আইন শাসন থেকে কঠিন নিয়ম নিয়ে এসেছি. বরং পাগলের ভিতরে ঢুকতে গিয়ে আমি অসুস্থ যে সে আর দশ বার ফিরে আসতে আশা করছে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَحَدٍ يَدْخُلُ الْجَنَّةَ يُحِبُّ أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَإِنَّ لَهُ مَا عَلَى الْأَرْضِ مِنْ شَيْءٍ غَيْرَ الشَّهِيدِ فَإِنَّهُ يَتَمَنَّى أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَيُقْتَلَ عَشْرَ مَرَّاتٍ لِمَا يَرَى مِنْ ‏ ‏الْكَرَامَةِ ‏","","",""],[13418,13418,"","আমরা চেষ্টা করে বলছি, আপনার টাকা বলে যে নবী বলেছেন, সবচেয়ে ভয়ঙ্কর মানুষদের প্রার্থনা করছেন।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ الْأَعْوَرُ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏مِنْ أَخَفِّ النَّاسِ صَلَاةً فِي تَمَامٍ ‏","","",""],[13419,13419,"","আমরা একটা রীতি আর দুই বার একটা যাজকের সাথে একটা রীতি তৈরি করেছি। ঈশ্বর তার কাছে প্রার্থনা করেছিলেন আর আমি বলবো আগুন থেকে বেরিয়ে আসতে আল্লাহ দোহাই দিয়ে বলেন, আমি আর আগুন থেকে বের হতে চাই না। আর অন্যদের হৃদয়ে কে ছিল, আমরা আল্লাহ আর ঈশ্বর বলে কথা বলেছি, আমি আগুনের বাইরে, আমরা একটা ষাঁড়ের বাচ্চা নিয়ে চিন্তা করছি যে অগ্নি থেকে বেরিয়ে এসেছে। বলা হয়েছে, এটা কখনোই হবে না, ডজন ডজন ডলারে কি পরিমাণ হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْرِجُوا مِنْ النَّارِ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَخْرِجُوا مِنْ النَّارِ ‏ ‏مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَمَنْ كَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ ذَرَّةً أَخْرِجُوا مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَمَنْ كَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ شَعِيرَةً أَخْرِجُوا مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَمَنْ كَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ ‏ ‏بُرَّةً ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَخْرِجُوا مِنْ النَّارِ فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏ابْنِ جَعْفَرٍ ‏ ‏وَزَادَ فِيهِ أَخْرِجُوا مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ دُودَةً ‏","","",""],[13420,13420,"","আমরা কিছু লোক নিয়ে কথা বলেছি একটু ঝামেলা করার চেষ্টা করছি। আমি আপনার টাকা ভুলতে ভুলে গেছি... ...যে নবী তাঁর কাছে প্রার্থনা করেছিলেন আর বলেছিলেন ফোন না করতে, প্রভু, যদি না চান, আমি নই। তোমার বাবা আর আমি বলে দিচ্ছি যে আমি কাঁপছি... ...নাকি আমার বাবাও মারা গেছে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏وَبَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تُوَاصِلُوا ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ إِنِّي لَسْتُ كَأَحَدِكُمْ إِنِّي أَبِيتُ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏إِنِّي أَظَلُّ ‏ ‏أَوْ أَبِيتُ ‏ ‏أُطْعَمُ وَأُسْقَى ‏","","",""],[13421,13421,"","আমরা কথা বলেছিলাম কিভাবে আমরা আমাকে ঈশ্বরের কাছে যেতে চেষ্টা করেছি. একজন লোক তাকে নিয়ে গিয়েছিল যে তাকে একজন যাজক হিসেবে.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى رَجُلٍ يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏قَالَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ‏ ‏وَيْحَكَ ‏ ‏أَوْ وَيْلَكَ ‏ ‏ارْكَبْهَا ‏","","",""],[13422,13422,"","আমরা বলতে পারি ঈশ্বর যে রক্ষা করেছেন এবং ঈশ্বরের শান্তি কামনা করছি, আমার ভবিষ্যদ্বাণী হয়তো তাকে মায়ের কাছে ডেকেছে এবং আমি আমার গুজবকে চিহ্নিত করেছি। মা।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ دَعْوَةً قَدْ دَعَا بِهَا فِي أُمَّتِهِ وَإِنِّي قَدْ اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي ‏","","",""],[13423,13423,"","আমরা এত টাকা নিয়ে কথা বলেছি যে আমরা তোমার টাকা ভুলে যাওয়ার কথা ভুলে যেতে চেয়েছিলাম। সে সবাইকে হত্যা করার জন্য সবাইকে সে বলেছে কতজন আছে যে তাদের কেউ একজন না বলে। বোন, সে তোমার বোনের একটা ছেলেকে দিয়ে আমার সাথে কথা বলার সময় পাশে এসে বলে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ ‏ ‏الْأَنْصَارَ ‏ ‏فَقَالَ هَلْ فِيكُمْ أَحَدٌ مِنْ غَيْرِكُمْ قَالُوا لَا إِلَّا ‏ ‏ابْنَ أُخْتٍ لَنَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْ أَنْفُسِهِمْ ‏ ‏وَقَالَ مَرَّةً مِنْهُمْ ‏ ‏فَحَدَّثَنِي بِهِ عَنْ ‏ ‏أَنَسٍ ‏","","",""],[13424,13424,"","আমরা হলে ধরা পড়ার কথা বলেছি, আল্লাহ হাতিয়ে দিয়েছেন আর ঈশ্বর তাকে উদ্ধার করেছেন। সে বলল, তুমি কি বলো?","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏يُسَلِّمُونَ عَلَيْنَا فَكَيْفَ نَرُدُّ عَلَيْهِمْ قَالَ قُولُوا وَعَلَيْكُمْ ‏","","",""],[13425,13425,"","আমরা কথা বলেছিলাম, সে কিভাবে মানুষকে হত্যা করতে চেষ্টা করলো, যারা বলেছে ঈশ্বর তাকে রক্ষা করেছে আর তার শান্তি আছে, আর রাগ করো না, হিংসা করো না আর ভাই হও।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَاَ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقَاطَعُوا وَلَا تَبَاغَضُوا وَلَا تَحَاسَدُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[13426,13426,"","আমরা বাবা'র কথা বলেছিলাম যে সে ছিল তার নিজের ক্ষমতা, লর্ডকে ফোন করতে... ...ভালো বছরের জন্য... শেষ জন, সে বলেছে আমি লোক বলছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَدْعُوَ ‏ ‏اللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَذَكَرْتُ ذَلِكَ ‏ ‏لِقَتَادَةَ ‏ ‏فَقَالَ ‏ ‏قَتَادَةُ ‏ ‏كَانَ ‏ ‏أَنَسٌ ‏ ‏يَقُولُ هَذَا ‏","","",""],[13427,13427,"","আমরা কথা বলেছিলাম কিভাবে আমি বলবো যে আমি গাছ সম্পর্কে ভুলে যাবো, ঈশ্বর তার কাছে প্রার্থনা করলেন আর তিনি বলেছিলেন, তিনি এমন কিছু করেছেন যা তিনি ঘৃণা করতেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسًا ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ لَمْ أَسْمَعْ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ شَيْئًا قَالَ وَكَانَ ‏ ‏أَنَسٌ ‏ ‏يَكْرَهُهُ ‏","","",""],[13428,13428,"","আমরা তাদের কথা বলেছি যারা ঈশ্বরের কাছে আছে এবং স্বপ্ন দেখে না, তারা তাকে স্পর্শ করবে এবং তার দিকে তাকিয়ে বলবে আমি চলে যাব.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِثَوْبٍ حَرِيرٍ فَجَعَلُوا يَمَسُّونَهُ وَيَنْظُرُونَ إِلَيْهِ فَقَالَ أَتَعْجَبُونَ مِنْ هَذَا لَمَنَادِيلُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏فِي الْجَنَّةِ خَيْرٌ مِنْ هَذَا وَأَلْيَنُ مِنْ هَذَا ‏ ‏أَوْ قَالَ مِنْدِيلُ ‏","","",""],[13429,13429,"","আমি ভেবেছিলাম, আমি আর ওর সাথে আছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي وَأَنَا مَعَهُ إِذَا دَعَانِي ‏","","",""],[13430,13430,"","আমরা একটি পুত্র হিসাবে একটি নিয়ম একটি নিয়ম কথা কথা কথা বলা যে একটি পুত্র যে যে বলেন যে তার এবং তার পুত্র একটি পুত্র হতে হয়.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ ‏","","",""],[13431,13431,"","আমরা কথা বলেছিলাম যে আমরা যেভাবে শুনতে চেয়েছিলাম তা শোনার চেষ্টা করলাম, ঈশ্বর তার জন্য প্রার্থনা করলেন আর তারপর প্রার্থনা করলেন আর উজ্জ্বল হবেন না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُونَ ثُمَّ يُصَلُّونَ وَلَا يَتَوَضَّئُونَ ‏","","",""],[13432,13432,"","আমরা খেলার সময় খুশি হয়েছি আর আমি যে যুক্তি পেয়েছি, ঈশ্বর তাকে নিয়ে এসেছেন আর আমি সব উদ্ধার করবো। আর একজন যুবক যে ছোট বয়সে জিতেছিল। মহিলা আর বাবা একজন শিকারী বলেছে আমি কে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏و حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شُعْبَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَمَعَ الْقُرْآنَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعَةٌ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏كُلُّهُمْ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏وَمُعَاذُ بْنُ جَبَلٍ ‏ ‏وَزَيْدُ بْنُ ثَابِتٍ ‏ ‏وَأَبُو زَيْدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏مَنْ ‏ ‏أَبُو زَيْدٍ ‏ ‏قَالَ ‏ ‏أَحَدُ عُمُومَتِي ‏","","",""],[13433,13433,"","আমি যে পানীয় খেতে বলেছিলাম সেই পানীয়র কথা বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نُهِيَ عَنْ الشُّرْبِ قَائِمًا قَالَ قُلْتُ فَالْأَكْلُ قَالَ ذَاكَ أَشَدُّ ‏","","",""],[13434,13434,"","আমরা সূর্যের মাঝে যে প্রথা কথা বলেছি তাতে খুশির কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏الْحَجَرُ الْأَسْوَدُ مِنْ الْجَنَّةِ ‏","","",""],[13435,13435,"","আমরা যারা কথা বলেছি তারা বলছে আমার বাবা একটি দানব এবং আমরা তার কথা শুনেছি. আমার বাবা একটি শ্বাসরুদ্ধকর গন্ধ এবং তর্ক করছি যে আমরা একটি দাঙ্গার সৃষ্টি করেছি. লোকেরা বলে যে, সেই ছেলেটিই ছিল সেই ব্যক্তি যিনি অন্যদের কথা শুনেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏وَأَبُو نُوحٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَبُو نُوحٍ ‏ ‏وسَمِعَهُ مِنْهُ ‏ ‏و حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏هَاشِمٍ ‏ ‏وَالْحَجَّاجِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَخَفِّ النَّاسِ صَلَاةً فِي تَمَامٍ ‏","","",""],[13436,13436,"","আমরা তর্কের কথা বলেছি, আমরা তোমার টাকা ভুলে যাবার কথা বলেছি, ঈশ্বরের বার্তাবাহক তার জন্য প্রার্থনা করেছে আর সে মানুষের সাথে যুদ্ধ করবে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَلَا أُحَدِّثُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَذْهَبُ الرِّجَالُ ‏ ‏وَيَبْقَى النِّسَاءُ ‏","","",""],[13437,13437,"","আমরা এমন লোকদের জন্য শাসক হওয়া নিয়ে কথা বলেছি যারা ঈশ্বরের কাছে প্রার্থনা করেছে, তারা ঐ কুঁচকের হাত থেকে রক্ষা করবে, তারা ঐ বানের দলটার কাছে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَلْمَدِينَةِ ‏ ‏يَأْتِيهَا ‏ ‏الدَّجَّالُ ‏ ‏فَيَجِدُ الْمَلَائِكَةَ ‏ ‏عَلَيْهِمْ السَّلَام ‏ ‏يَحْرُسُونَهَا فَلَا يَقْرَبُهَا ‏ ‏الدَّجَّالُ ‏ ‏وَلَا الطَّاعُونُ إِنْ شَاءَ اللَّهُ تَعَالَى ‏","","",""],[13438,13438,"","আমরা সেই লোকদের কথা বলেছি যারা ভবিষ্যদ্বাণীর জন্য কিভাবে যুদ্ধ করতে হয়। আর তারপর আমি একজন টাক-মানুষের ছেলের কথা বলেছিলাম যে আমাদের একজন যাজক হওয়ার কথা বলেছিল। আর আমার বাবা আমাদের সাথে কথা বলেছে আমাদের আরও ভাল করে কথা বলেছে। ( মথি ২৪: ১৪) তাই, আপনার কাছে যে - অর্থ রয়েছে, তা হল আপনার বিশ্বাস, আপনার বিশ্বাস, বিশ্বাস এবং বিশ্বাস । অমর, একটা পরিকল্পনা পেয়ে আমি তাকে বাঁচিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنِي ‏ ‏الضَّحَّاكُ يَعْنِي ابْنَ مَخْلَدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْوَاسِطِيُّ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتُوَائِيِّ ‏ ‏وَشُعْبَةَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ الْبُزَاقُ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏وَالضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏فِي حَدِيثِهِمَا ‏ ‏النُّخَاعَةُ ‏ ‏فِي الْمَسْجِدِ خَطِيئَةٌ وَكَفَّارَتُهَا دَفْنُهَا ‏","","",""],[13439,13439,"","আমরা কথা বলেছিলাম সে তোমার টাকা ভুলে যাবে, তাকে হার মানতে হবে ভালো ছাত্র হতে না বলে, আর আমি বলতে চাই, আমি কথা বলতে ও কথা বলতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏أَخْبَرَنِي أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَيُعْجِبُنِي الْفَأْلُ ‏ ‏قُلْتُ وَمَا الْفَأْلُ ‏ ‏قَالَ ‏ ‏الْكَلِمَةُ الطَّيِّبَةُ ‏","","",""],[13440,13440,"","আমরা বাবার ট্যাক্সির মৃত্যু নিয়ে কথা বলেছি। লর্ড তার জন্য প্রার্থনা করলেন। আর আমাদের মৃত্যুর জন্য প্রার্থনা করলেন। তাদের মধ্যে একজন অন্যটা আছে।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏وَقَتَادَةَ ‏ ‏وَحَمْزَةَ الضَّبِّيِّ ‏ ‏أَنَّهُمْ سَمِعُوا ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُعِثْتُ أَنَا وَالسَّاعَةُ هَكَذَا وَأَشَارَ بِالسَّبَّابَةِ وَالْوُسْطَى ‏ ‏وَكَانَ ‏ ‏قَتَادَةُ ‏ ‏يَقُولُ ‏ ‏كَفَضْلِ إِحْدَاهُمَا عَلَى الْأُخْرَى ‏","","",""],[13441,13441,"","আমরা এক বছর ধরে কালো পুত্র সম্পর্কে কথা বলেছি আমরা এক প্রথা পালন করেছি যারা আমার প্রভুর ইচ্ছা ভুলে গেছে, সে অভিশাপ দেয় এবং তাকে পাহারা দেয়।","‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏شَهْرًا يَلْعَنُ ‏ ‏رِعْلًا ‏ ‏وَذَكْوَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏عَصَوْا اللَّهَ وَرَسُولَهُ ‏","","",""],[13442,13442,"","আমরা বাবা'র সাথে কথা বলেছি একটা উলকি বানাতে পেরে খুশি হয়েছি যে ঈশ্বর শাসন করার চেষ্টা করেছেন আর হাতি আর আমার ছেলে কাঠবিড়াল আর চোর ওর ছেলে, আমি বলেছি তুই নাকি কখনো না বলে দিয়ে যা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا يَدْعُو عَلَى ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَبَنِي فُلَانٍ ‏ ‏وَعُصَيَّةَ ‏ ‏عَصَوْا اللَّهَ وَرَسُولَهُ ‏ ‏قَالَ ‏ ‏مَرْوَانُ ‏ ‏يَعْنِي فَقُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏قَنَتَ ‏ ‏عُمَرُ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏لَا ‏","","",""],[13443,13443,"","আমি ঈশ্বরের কাছে শপথ করে বলছি যে, তিনি নিজের হাত পূর্ণ করতে ব্যর্থ হবেন এবং তাকে ধ্বংস করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي صَلَاةٍ فَإِنَّهُ ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ عَزَّ وَجَلَّ فَلَا يَتْفِلَنَّ بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلْيَتْفِلْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ ‏","","",""],[13444,13444,"","আমরা একটি নির্দিষ্ট খারাপ সঙ্গে কথা করেছি, আমরা একটি বছর বয়সী হতে খুশি, আমরা একটি বিচার শাসন চেষ্টা করেছি তার জন্য প্রার্থনা এবং তিনি আমাদের অনেক বলেছেন যে তিনি আমাদের কাছে ক্ষমা প্রার্থনা করবেন ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُلَاطِفُنَا كَثِيرًا حَتَّى إِنَّهُ قَالَ لِأَخٍ لِي صَغِيرٍ ‏ ‏يَا ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏","","",""],[13445,13445,"","আমি কথা বলার চেষ্টা করেছি। সে তাদের বলেছিল, অন্য আরেকজন যেন হারিয়ে না যায়। দাঙ্গা তার গল্পে বলছে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنَّ الْخَيْرَ خَيْرُ ‏ ‏الْآخِرَهْ أَوْ قَالَ ‏ ‏اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرَ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏كَانَ يَقُولُ ‏ ‏قَتَادَةُ ‏ ‏هَذِهِ فِي قَصَصِهِ ‏","","",""],[13446,13446,"","আমরা আগেও বলেছি কত মানুষ এটা করেছে আর করেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَبَحَ وَسَمَّى وَكَبَّرَ ‏","","",""],[13447,13447,"","আমরা ঈশ্বর সম্পর্কে কথা বলেছিলাম কিন্তু ঈশ্বর আমাদের কথা বলেছেন আমরা কত কঠিন চেষ্টা করেছি। আমি তার জন্য প্রার্থনা করেছিলাম এবং সে আমার বাবার মন অনেক বার শপথ করতো। সে যা বলেছে, তাতে খুশি থেকো, তারা আমাকে ঈশ্বরের অনুগ্রহের কথা বলতে ক্ষমা করবে, আমরা জানি আমরা তাকে এর জন্য জিজ্ঞাসা করব।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَلْفَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمْ ‏ ‏فَلَمْ يَكُونُوا يَسْتَفْتِحُونَ الْقِرَاءَةَ بِ ‏ { ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏} ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ ‏ ‏لِقَتَادَةَ ‏ ‏أَسَمِعْتَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏نَعَمْ نَحْنُ سَأَلْنَاهُ عَنْهُ ‏","","",""],[13448,13448,"","আমরা ঈশ্বর সম্পর্কে কথা বলেছি বাবা কিন্তু ঈশ্বর আমার মন পরিবর্তন করেছেন আমি বলছি, চাঁদ কেটে গেছে","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏انْشَقَّ ‏ ‏الْقَمَرُ عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13449,13449,"","আমরা কিভাবে ঈশ্বর সম্পর্কে জানতে চেষ্টা এবং তিনি কখনো তা করেননি। আমি বিশ্বাস করি যে ঈশ্বরও এটা পছন্দ করবেন। আমাদের নিশ্চিত করতে হবে যে, ঈশ্বর তা করেন না। বিশ্বাস করো, যতক্ষণ না আমি তাকে তার নিজের ছেলে এবং আমি যাকে ভালোবাসি তার কথা শুনেছি। তার জন্য এসেছে, তার মত।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَحَتَّى يُقْذَفَ فِي النَّارِ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَعُودَ فِي كُفْرٍ بَعْدَ إِذْ نَجَّاهُ اللَّهُ مِنْهُ وَلَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَلَدِهِ وَوَالِدِهِ وَالنَّاسِ أَجْمَعِينَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَنْصُورًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏طَلْقَ بْنَ حَبِيبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[13450,13450,"","বাবা আমার সঙ্গে আমার কথা বলেছিলেন কিন্তু ঈশ্বর আমাকে আমার জীবন সম্বন্ধে বলেছিলেন । গুলি করো.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَرَمِيُّ بْنُ عُمَارَةَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏وَحَمَّادُ بْنُ أَبِي سُلَيْمَانَ ‏ ‏وَسُلَيْمَانُ التَّيْمِيُّ ‏ ‏سَمِعُوا ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[13451,13451,"","আমরা কথা বলেছি যে শাসন কতটা কঠিন... ...আমরা তোমার টাকা ভুলে গেছি যে ঈশ্বর হয়ত আজীবন মৃত্যুর সম্মুখীন হয়েছেন.","‏ ‏حَدَّثَنَا ‏ ‏شَبَابَةُ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏تَزَوَّجَ عَلَى وَزْنِ ‏ ‏نَوَاةٍ ‏ ‏مِنْ ذَهَبٍ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏الْحَكَمُ ‏ ‏يَأْخُذُ بِهِ ‏","","",""],[13452,13452,"","আমরা ঈশ্বরের প্রেমে... ...আমার বাবার সাথে দেখা হওয়া প্রফেসরের সাথে কথা বলেছি, ঈশ্বর এটা উদ্ধার করতে হবে আর আমি তোমাকে বিশ্বাস করব না যে তুমি তার ভাই পছন্দ কর.","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ ‏","","",""],[13453,13453,"","বাবা নিজেকে রক্ষা করার চেষ্টা নিয়ে বাবার সাথে কথা বলেছিলাম। সে বলল, ঈশ্বর তার জন্য প্রার্থনা করুক। আর সে আত্মা থেকে আত্মসমর্পণ করবে ঈশ্বরের দোহাই এবং ঈশ্বরের দোহাই। ঈশ্বরের দোহাই, ঈশ্বরের দোহাই, ঈশ্বরের দোহাই, আমি মরে যাব, তার ধর্ম আছে এবং সে সেই সাক্ষী নয় যে ঋণের মধ্যে মারা যাবে, শহীদদের দেখতে পাবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَشُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ نَفْسٍ تَمُوتُ لَهَا عِنْدَ اللَّهِ عَزَّ وَجَلَّ خَيْرٌ يَسُرُّهَا أَنْ تَرْجِعَ إِلَى الدُّنْيَا وَأَنَّ لَهَا الدُّنْيَا وَمَا فِيهَا إِلَّا الشَّهِيدَ ‏ ‏يَتَمَنَّى أَنْ يَرْجِعَ فَيُقْتَلَ فِي الدُّنْيَا لِمَا يَرَى مِنْ ‏ ‏فَضْلِ الشَّهَادَةِ ‏","","",""],[13454,13454,"","আমরা ঈশ্বর সম্পর্কে কথা বলেছিলাম কিন্তু বাবা আমাদের এত কষ্ট করে কথা বলেছে। ঈশ্বরের দয়া ছিল তাঁর ইচ্ছা আর তাকে সবচেয়ে ভয়ঙ্কর লোকদের হাত থেকে উদ্ধার করা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَخَفِّ النَّاسِ صَلَاةً فِي تَمَامٍ ‏","","",""],[13455,13455,"","বাবা আমাদের ফোন করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏سَمِعَ ‏ ‏أَنَسًا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُعْجِبُهُ ‏ ‏الدُّبَّاءُ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَجَعَلْتُ أَضَعُهُ بَيْنَ يَدَيْهِ ‏","","",""],[13456,13456,"","প্রতিবেশী বলেছে, আমি ভাববাদীর কাছ থেকে কিছু শুনি নাই।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسًا ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ لَمْ أَسْمَعْ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ شَيْئًا وَكَانَ ‏ ‏أَنَسٌ ‏ ‏يَكْرَهُهُ ‏","","",""],[13457,13457,"","আমরা ঈশ্বরের ভাগ্যের কথা বলেছি, তাকে হত্যা করার চেষ্টা করে... ...সে বলল, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি আগুনের মধ্যে দিয়ে যাবেন এবং বলেন \"আমি অনেক বেশি\" এবং \"আমি ঈশ্বরের ভাগ্যের কথা বলছি\" তুমি শুধু বললে","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِىُّ ‏ ‏حَدَّثَنَا ‏ ‏حَرَمِيُّ بْنُ عُمَارَةَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلْقِي فِي النَّارِ وَتَقُولُ ‏ { ‏هَلْ مِنْ مَزِيدٍ ‏} ‏حَتَّى يَضَعَ قَدَمَهُ ‏ ‏أَوْ رِجْلَهُ ‏ ‏عَلَيْهَا وَتَقُولُ قَطْ قَطْ ‏","","",""],[13458,13458,"","আমরা পাগল হয়ে যাওয়ার চেষ্টা করেছি। আমি ভুলে গেছি যে খোদা তাঁর কাছে প্রার্থনা করেছে আর যদি তারা ক্ষমা চাইতে চায় তাহলে তারা তা পৌঁছে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَحْمَدَ الْجُنَيْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَكَانَ بِهَذَا الْحَدِيثِ مُعْجَبًا ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَوُّوا صُفُوفَكُمْ فَإِنَّ تَسْوِيَةَ الصَّفِّ مِنْ تَمَامِ الصَّلَاةِ ‏","","",""],[13459,13459,"","আমরা ঈশ্বরের ভাগ্য কথা বলেছি, তাকে হত্যা করার চেষ্টা করে... ...তোমার টাকা তার কাছে প্রার্থনা করে তাকে আমি যাদের কাছে মিথ্যা বলতে চেয়েছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَرَمِيُّ بْنُ عُمَارَةَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[13460,13460,"","আমরা আমাদের বাবার সাথে ঈশ্বরের হাত নিয়ে কথা বলেছিলাম, সে বলেছিল আমরা জন্মগ্রহণ করেছি আর বাবা ছিলেন শিকারী যে তার কাছ থেকে খেয়েছিল.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مُطِرْنَا ‏ ‏بَرَدًا ‏ ‏وَأَبُو طَلْحَةَ ‏ ‏صَائِمٌ فَجَعَلَ يَأْكُلُ مِنْهُ قِيلَ لَهُ أَتَأْكُلُ وَأَنْتَ صَائِمٌ فَقَالَ إِنَّمَا هَذَا بَرَكَةٌ ‏","","",""],[13461,13461,"","আমরা ঈশ্বরের সাথে কথা বলেছি যে আমি আমার ভ্রাতৃসমাজের আনন্দে ফিরে যাব। বড় হয়ে তাকে হাত ও আত্মা দিয়ে যেতে দেখা।","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ سَعْدِ بْنِ إِبْرَاهِيمَ الزُّهْرِيُّ أَبُو الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ بْنِ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَحِّي بِكَبْشَيْنِ أَقْرَنَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏وَيُسَمِّي وَيُكَبِّرُ وَلَقَدْ رَأَيْتُهُ يَذْبَحُهُمَا بِيَدِهِ وَاضِعًا عَلَى ‏ ‏صِفَاحِهِمَا ‏ ‏قَدَمَهُ ‏","","",""],[13462,13462,"","আমরা ঈশ্বরের ভাল কথা নিয়ে কথা বলেছি যে আমার চাচা তোমাকে মেরে ফেলবে একটা জীবন পাওয়ার জন্য, তোমার আত্মাকে না মানলে, আমি তোমার কাছে আসি, আর প্রভু তোমার হিসাব অনুসারে তোমাকে দেখি,","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏يَعْقُوبُ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اعْتَدِلُوا فِي سُجُودِكُمْ وَلَا ‏ ‏يَفْتَرِشْ ‏ ‏أَحَدُكُمْ ذِرَاعَيْهِ ‏ ‏افْتِرَاشَ ‏ ‏الْكَلْبِ أَتِمُّوا الرُّكُوعَ وَالسُّجُودَ فَوَاللَّهِ إِنِّي لَأَرَاكُمْ مِنْ بَعْدِي ‏ ‏أَوْ مِنْ بَعْدِ ظَهْرِي ‏ ‏إِذَا رَكَعْتُمْ وَإِذَا سَجَدْتُمْ ‏","","",""],[13463,13463,"","আমরা ঈশ্বর সম্বন্ধে কথা বলেছিলাম, বেন দুরকিকে ফোন করে কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ الدَّوْرَقِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ عُمُومَةً لَهُ شَهِدُوا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رُؤْيَةِ الْهِلَالِ ‏ ‏فَأَمَرَ النَّاسَ أَنْ يُفْطِرُوا وَأَنْ يَخْرُجُوا إِلَى عِيدِهِمْ مِنْ الْغَدِ ‏","","",""],[13464,13464,"","আমরা ইশ্বরের সাথে কথা বলেছি কিন্তু বাবা আমাদের বলেছে যে তারা মহিলা আর ছেলেদের সাথে ঘুমোচ্ছে আর গান গাইতে বলেছে, সে এগিয়ে চলে গেছে আর সে কিভাবে বলেছে, সৃষ্টিকর্তা বলেছেন, ঈশ্বর বলেছেন, \"আমি প্রভু এবং ঈশ্বরকে ভালবাসি,\" তারা তলোয়ার দিয়ে মারে, এমনকি তারা বলতে পারে না যে ঈশ্বর এটা করেছেন, তিনি তাদের বাবাকে হত্যা করেছেন, এবং তিনি একজন মানুষকে হত্যা করতে পারেন। আর তাদের পিল গুলি নিয়ে নাও, ইমাম তার জন্য বানিয়ে ফেলেছে আর আমি হয়তো বলতে পারি সে অনেক অমর. সে বলেছে আমি তাকে নিয়ে ফেলেছি, আর সে এটা করবে. ঈশ্বর তাকে ধরে নিয়ে যাবেন আর তিনি বলবেন যে তিনি তার পালনকরকে হত্যা করেছেন। সে তার জন্য প্রার্থনা করতো আর ছেলেটির দয়ায় সে মারা যেত। আমার বাবা একটা সালাদ আর তার একটা বস ছিল। আমি বলতে চাই, আমার বাবা একজন পেইন্টার, যে তোমার কথা শোনে না। তোমাকে মারুন, বল যে ঈশ্বর হয়তো থেমে গেছেন আর ভাল আছেন মা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏هَوَازِنَ ‏ ‏جَاءَتْ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏بِالنِّسَاءِ وَالصِّبْيَانِ وَالْإِبِلِ وَالْغَنَمِ فَجَعَلُوهَا صُفُوفًا وَكَثُرْنَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا الْتَقَوْا ‏ ‏وَلَّى ‏ ‏الْمُسْلِمُونَ ‏ ‏مُدْبِرِينَ ‏ ‏كَمَا قَالَ اللَّهُ عَزَّ وَجَلَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا عِبَادَ اللَّهِ ‏ ‏أَنَا عَبْدُ اللَّهِ وَرَسُولُهُ ثُمَّ قَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَنَا عَبْدُ اللَّهِ وَرَسُولُهُ قَالَ فَهَزَمَ اللَّهُ الْمُشْرِكِينَ وَلَمْ يَضْرِبُوا بِسَيْفٍ وَلَمْ يَطْعَنُوا بِرُمْحٍ قَالَ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ مَنْ قَتَلَ كَافِرًا فَلَهُ ‏ ‏سَلَبُهُ ‏ ‏قَالَ فَقَتَلَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَوْمَئِذٍ عِشْرِينَ رَجُلًا وَأَخَذَ ‏ ‏أَسْلَابَهُمْ ‏ ‏وَقَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏يَا رَسُولَ اللَّهِ إِنِّي ضَرَبْتُ رَجُلًا عَلَى ‏ ‏حَبْلِ الْعَاتِقِ ‏ ‏وَعَلَيْهِ ‏ ‏دِرْعٌ ‏ ‏لَهُ ‏ ‏وَأُجْهِضْتُ ‏ ‏عَنْهُ ‏ ‏وَقَدْ قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَيْضًا فَأُعْجِلْتُ عَنْهُ ‏ ‏فَانْظُرْ مَنْ أَخَذَهَا قَالَ فَقَامَ رَجُلٌ فَقَالَ أَنَا أَخَذْتُهَا فَأَرْضِهِ مِنْهَا وَأَعْطِنِيهَا وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُسْأَلُ شَيْئًا إِلَّا أَعْطَاهُ أَوْ سَكَتَ قَالَ فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏وَاللَّهِ لَا ‏ ‏يُفِيئُهَا ‏ ‏اللَّهُ عَلَى أَسَدٍ مِنْ أُسْدِهِ ‏ ‏وَيُعْطِيكَهَا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏ ‏عُمَرُ ‏ ‏فَضَحِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ صَدَقَ ‏ ‏عُمَرُ ‏ ‏وَلَقِيَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَمَعَهَا خِنْجَرٌ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏مَا هَذَا مَعَكِ قَالَتْ أَرَدْتُ إِنْ دَنَا مِنِّي بَعْضُ الْمُشْرِكِينَ أَنْ ‏ ‏أَبْعَجَ ‏ ‏بِهِ بَطْنَهُ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏أَلَا تَسْمَعُ مَا تَقُولُ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ اقْتُلْ مَنْ بَعْدَنَا مِنْ ‏ ‏الطُّلَقَاءِ ‏ ‏انْهَزَمُوا بِكَ فَقَالَ إِنَّ اللَّهَ قَدْ كَفَى وَأَحْسَنَ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏","","",""],[13465,13465,"","আমরা একটা বাচ্চা থাকার কথা বলেছিলাম কিন্তু একটা বাচ্চা থাকার কথা, কেন সে দুটো প্রাণীর সাথে ঘুমাচ্ছিলো, যাদেরকে ঈশ্বরের দোহাইর চেয়েও গ্রেপ্তার করা হয়েছিল এবং স্বপ্নের চেয়ে বেশি কিছু চাইতে বলা হয়েছিল। ১০ হাজার কিংবা দশ বছরের একটা মই, আর হঠাৎ করে তাকে মুখস্ত বলে। তিনি স্লিপিংয়ে গিয়েছিলেন এবং বলেছিলেন যে, ঈশ্বর আমাকে আঘাত করবেন এবং তিনি কখনো ফোন করবেন না । এরপর আমরা এটাকে সর্বোত্তম উপায়ে অনুসরণ করি । ১০ জন জেনারেলের সাথে কখনো দেখা হয়নি। সবাই বন্ধু হয়ে থাকবে। ঈশ্বর আপনাকে বলতে হবে যে তিনি আমাদের সন্তুষ্ট করেছেন, প্রভু। আমি আপনাকে বলছি আপনি এমন লোকদের কাছে বলছেন যেখানে আমি মিস করি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ أَخْضَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏حَدَّثَنِي ‏ ‏هِشَامُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏حُنَيْنٍ ‏ ‏وَجَمَعَتْ ‏ ‏هَوَازِنُ ‏ ‏وَغَطَفَانُ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمْعًا كَثِيرًا وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ فِي عَشَرَةِ آلَافٍ ‏ ‏أَوْ أَكْثَرَ مِنْ عَشَرَةِ آلَافٍ ‏ ‏قَالَ وَمَعَهُ ‏ ‏الطُّلَقَاءُ ‏ ‏قَالَ فَجَاءُوا بِالنَّعَمِ ‏ ‏وَالذُّرِّيَّةِ ‏ ‏فَجُعِلُوا خَلْفَ ظُهُورِهِمْ قَالَ فَلَمَّا الْتَقَوْا ‏ ‏وَلَّى ‏ ‏النَّاسُ قَالَ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ عَلَى بَغْلَةٍ بَيْضَاءَ قَالَ فَنَزَلَ وَقَالَ إِنِّي عَبْدُ اللَّهِ وَرَسُولُهُ قَالَ وَنَادَى يَوْمَئِذٍ نِدَاءَيْنِ لَمْ يُخْلَطْ بَيْنَهُمَا كَلَامٌ فَالْتَفَتَ عَنْ يَمِينِهِ فَقَالَ أَيْ مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا لَبَّيْكَ يَا رَسُولَ اللَّهِ أَبْشِرْ نَحْنُ مَعَكَ ثُمَّ الْتَفَتَ عَنْ يَسَارِهِ فَقَالَ أَيْ مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا لَبَّيْكَ يَا رَسُولَ اللَّهِ نَحْنُ مَعَكَ ثُمَّ نَزَلَ بِالْأَرْضِ وَالْتَقَوْا فَهَزَمُوا وَأَصَابُوا مِنْ الْغَنَائِمِ فَأَعْطَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطُّلَقَاءَ ‏ ‏وَقَسَمَ فِيهَا فَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏نُدْعَى عِنْدَ الْكَرَّةِ وَتُقْسَمُ الْغَنِيمَةُ لِغَيْرِنَا فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَمَعَهُمْ وَقَعَدَ فِي ‏ ‏قُبَّةٍ ‏ ‏فَقَالَ أَيْ مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏مَا حَدِيثٌ بَلَغَنِي عَنْكُمْ فَسَكَتُوا ثُمَّ قَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏لَوْ أَنَّ النَّاسَ سَلَكُوا وَادِيًا وَسَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏شِعْبًا ‏ ‏لَأَخَذْتُ ‏ ‏شِعْبَ ‏ ‏الْأَنْصَارِ ‏ ‏ثُمَّ قَالَ أَمَا تَرْضَوْنَ أَنْ يَذْهَبَ النَّاسُ بِالدُّنْيَا وَتَذْهَبُونَ بِرَسُولِ اللَّهِ ‏ ‏تَحُوزُونَهُ ‏ ‏إِلَى بُيُوتِكُمْ قَالُوا رَضِينَا يَا رَسُولَ اللَّهِ رَضِينَا ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏قَالَ ‏ ‏هِشَامُ بْنُ زَيْدٍ ‏ ‏فَقُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏وَأَنْتَ تُشَاهِدُ ذَاكَ قَالَ ‏ ‏فَأَيْنَ أَغِيبُ عَنْ ذَاكَ ‏","","",""],[13466,13466,"","আমরা দুজন সালাম নিয়ে যুদ্ধ করেছি, যা আপনাদের টাকার ভুলে যাওয়ার জন্য একটা দাস হয়ে গেছে। ঈশ্বর আদেশ দিয়েছেন, তার প্রভুর কাছে তার ইচ্ছা পালন করতে হবে। তার প্রভুর কাছে এসে তিনি তার নিয়তিকে ফিরে পাবেন । আমি আগুন থেকে রক্ষা করছি.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏غُلَامًا ‏ ‏يَهُودِيًّا كَانَ يَخْدُمُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرِضَ فَأَتَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُهُ ‏ ‏فَقَعَدَ عِنْدَ رَأْسِهِ فَقَالَ لَهُ أَسْلِمْ فَنَظَرَ إِلَى أَبِيهِ وَهُوَ عِنْدَ رَأْسِهِ فَقَالَ أَطِعْ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَأَسْلَمَ فَخَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ عِنْدِهِ وَهُوَ يَقُولُ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي أَنْقَذَهُ بِي مِنْ النَّارِ ‏","","",""],[13467,13467,"","আমরা একজন তরুণীর কথা বলেছিলাম যে তাকে ভুলে যাবে না যে দাস হওয়ার স্বপ্ন ছিল, ঈশ্বর তাকে আদেশ দিয়েছেন আর তিনি তার শান্তি ফিরে আসবেন আল্লাহ, অন্ধকারের মধ্যে তার পিতা এবং তার নাম তার পিতা তার জীবন মেনে চলে, সে তার নিজের থেকে উদ্ধার লাভ করে এবং সে বলে যে, মরূম যে আমাকে রক্ষা করেছে, সে তার জন্য সে ঐ মরূদ্যাদের হাত থেকে রক্ষা করেছে। আগুন.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ غُلَامًا مِنْ ‏ ‏الْيَهُودِ ‏ ‏كَانَ يَخْدُمُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرِضَ فَأَتَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُهُ ‏ ‏وَهُوَ بِالْمَوْتِ فَدَعَاهُ إِلَى الْإِسْلَامِ فَنَظَرَ الْغُلَامُ إِلَى أَبِيهِ وَهُوَ عِنْدَ رَأْسِهِ فَقَالَ لَهُ أَبُوهُ أَطِعْ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَأَسْلَمَ ثُمَّ مَاتَ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ عِنْدِهِ وَهُوَ يَقُولُ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي أَنْقَذَهُ بِي مِنْ النَّارِ ‏","","",""],[13468,13468,"","আমরা শপথ নিয়ে কথা বলেছি যার মানে হল তারা আমার কথা শুনেছে যা আমি তাকে কখনো বলিনি।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى يَعْنِي ابْنَ طَهْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدِي سِرًّا لَا أُخْبِرُ بِهِ أَحَدًا أَبَدًا حَتَّى أَلْقَاهُ ‏","","",""],[13469,13469,"","সে বলে, আমি ইচ্ছে করে তার অবস্থানকে বলেছি","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ طَهْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[13470,13470,"","আমরা কথা বলেছিলাম, আমার বাবা কিভাবে আমাদের তাঁর দৃষ্টি সম্পর্কে জানতে সাহায্য করেছিলেন। ঈশ্বরের কাছে এটা তুলে ধরতে হয়েছে যে, তিনি ভালোবাসা তৈরি করেছেন এবং বলছেন যে আপনার ছেলের সাথে আপনার ছেলের একটা বড় ঝগড়া আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ جَمَعَ بَيْنَ الْعُمْرَةِ وَالْحَجِّ فَقَالَ ‏ ‏لَبَّيْكَ بِحَجَّةٍ وَعُمْرَةٍ مَعًا ‏","","",""],[13471,13471,"","আমরা তাদের সম্পর্কে কথা বলেছি, তাকে নিয়ে আমাদের কথা বলা হয়েছে, আমি এমন এক মেয়ের সাথে কথা বলব যে তার বন্ধুদের তৈরি করেছে।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏أَخْبَرَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ ابْنَةَ حُيَيٍّ ‏ ‏وَجَعَلَ عِتْقَهَا ‏ ‏صَدَاقَهَا ‏","","",""],[13472,13472,"","আমরা একটা আবেগ নিয়ে কথা বলেছি... ...যে তোমাকে হত্যা করতে চাচ্ছে তার কথা শুনেছি। ( গীতসংহিতা ৩৭: ১১) ঈশ্বরের কাছে নিজেকে উৎসর্গ করা এবং সেগুলো হল, তোমরা যেন জেগে থাকো এবং পৃথিবীর স্বপ্ন ও স্বপ্নের সামনে দৌড়েছ ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ عَامِرٍ الْأَنْصَارِيَّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ الْمُؤَذِّنُ إِذَا أَذَّنَ قَامَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْتَدِرُونَ ‏ ‏السَّوَارِيَ ‏ ‏حَتَّى يَخْرُجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُمْ كَذَلِكَ ‏ ‏يَعْنِي الرَّكْعَتَيْنِ قَبْلَ الْمَغْرِبِ ‏ ‏وَلَمْ يَكُنْ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ إِلَّا قَرِيبٌ ‏","","",""],[13473,13473,"","আমরা বাবার সাথে কথা বলেছিলাম যখন আমরা জানতে যাব, আমাকে আমার সাথে যেতে হবে, যে আমাকে মারতে রাজি হবে। আর একবার আমি কিভাবে বলবো। তারপর আমি বলতে চাই যে একটি গৌরব এবং মুখ দিয়ে কথা বলার সাথে সাথে আপনার টাকা আমার মানুষের উপর ঈশ্বরের শান্তি এনে দিয়েছে এবং তাকে জিজ্ঞেস করেছে যে, এটা করতে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏مَوْلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ ‏ ‏عَلِيٍّ ‏ ‏فَأَتَيْنَا ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏إِنِّي أُرِيدُ أَنْ أَجْمَعَ بَيْنَ الْحَجِّ وَالْعُمْرَةِ فَمَنْ أَرَادَ ذَلِكَ فَلْيَقُلْ كَمَا أَقُولُ ثُمَّ لَبَّى قَالَ لَبَّيْكَ بِحَجَّةٍ وَعُمْرَةٍ مَعًا ‏ ‏قَالَ وَقَالَ ‏ ‏سَالِمٌ ‏ ‏وَقَدْ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ وَاللَّهِ إِنَّ رِجْلِي لَتَمَسُّ رِجْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّهُ ‏ ‏لَيُهِلُّ ‏ ‏بِهِمَا جَمِيعًا ‏","","",""],[13474,13474,"","আমরা মাস্টারকে সাহায্য করার কথা বলেছিলাম, সে যে কথা বলেছে তা ভুলে যাবো, ঈশ্বর তাকে আদেশ দিয়েছেন আর তার ছেলেকে তার আশীর্বাদের জন্য তাকে আত্মসমর্পণ করবে। আমি বললাম, ঈশ্বর যেন তাকে রক্ষা না করেন। আমি বললাম, আমি বললাম, \"আমি জানি,\" কিভাবে সময় কাটাব যদি আমি নিজের অধিকার অথবা আমার গোপন কথা ঠিক করার জন্য.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ السُّدِّيِّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ابْنِهِ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ لَا أَدْرِي رَحْمَةُ اللَّهِ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏لَوْ عَاشَ كَانَ صِدِّيقًا نَبِيًّا قَالَ قُلْتُ كَيْفَ أَنْصَرِفُ إِذَا صَلَّيْتُ عَنْ يَمِينِي أَوْ عَنْ يَسَارِي قَالَ أَمَّا أَنَا فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْصَرِفُ عَنْ يَمِينِهِ ‏","","",""],[13475,13475,"","আমরা মানুষের কথা বলেছিলাম যে আল্লাহ তার জন্য প্রার্থনা করেছেন আর তিনি লর্ডকে ধোঁকা দেয়ার চেষ্টা করবেন না। তার বাড়িতে শিকারী.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏وَقَالَ لَهُ قَائِلٌ بَلَغَكَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا ‏ ‏حِلْفَ ‏ ‏فِي الْإِسْلَامِ قَالَ فَغَضِبَ ثُمَّ قَالَ بَلَى بَلَى قَدْ ‏ ‏حَالَفَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏قُرَيْشٍ ‏ ‏وَالْأَنْصَارِ ‏ ‏فِي دَارِهِ ‏","","",""],[13476,13476,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছিলেন এবং চোরাকারবারীদের রক্ষা করেছিলেন এবং ভুলে যাওয়ার ঘরে জয়ের কথা ভুলে যাওয়ার জন্য ঘরে ছিলেন । তোমার টাকা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏حَالَفَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏فِي دَارِ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏","","",""],[13477,13477,"","আমরা হামাদ বান সেলমা সম্বন্ধে কথা বলেছিলাম, আমরা ভালো ও ভালোর বিষয়ে কথা বলেছিলাম । পিপাসা, যেখানে সে উড়ে যায়, সে মানুষের কাছে যায়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏وَعَنْ ‏ ‏أَنَسٍ ‏ ‏فِيمَا يَحْسَبُ ‏ ‏حَمَّادٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ ‏ ‏يَتَوَكَّأُ ‏ ‏عَلَى ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏وَهُوَ ‏ ‏مُتَوَشِّحٌ ‏ ‏بِثَوْبِ قُطْنٍ قَدْ ‏ ‏خَالَفَ ‏ ‏بَيْنَ طَرَفَيْهِ فَصَلَّى بِالنَّاسِ ‏","","",""],[13478,13478,"","আমরা কথা বলেছি যারা যৌন সম্পর্ক করার অভিযোগে অভিযুক্ত তাদের খুঁজে বের করার ব্যাপারে... তার কোনো ধারণাই নেই যে, ঈশ্বরের কাছে প্রার্থনা করেছেন তাকে হত্যা করার জন্য তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَجُلًا كَانَ يُتَّهَمُ بِامْرَأَةٍ ‏ ‏فَبَعَثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيًّا ‏ ‏لِيَقْتُلَهُ فَوَجَدَهُ فِي ‏ ‏رَكِيَّةٍ ‏ ‏يَتَبَرَّدُ ‏ ‏فِيهَا فَقَالَ لَهُ نَاوِلْنِي يَدَكَ فَنَاوَلَهُ يَدَهُ فَإِذَا هُوَ ‏ ‏مَجْبُوبٌ ‏ ‏لَيْسَ لَهُ ذَكَرٌ فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ وَاللَّهِ يَا رَسُولَ اللَّهِ إِنَّهُ ‏ ‏لَمَجْبُوبٌ ‏ ‏مَا لَه مِنْ ذَكَرٍ ‏","","",""],[13479,13479,"","আমার ব্যাপারে কিছু করার কথা বলে আমার বাবার সাথে কথা বলেছি। ঈশ্বর বলেছেন, আমি আমার বাবাকে ভালোবাসি, আমি আমার বাবাকে ঈশ্বরের ঋণের ব্যাপারে যতটা ভালবাসি, ঈশ্বর তার চেয়ে অনেক বেশি মূল্যবান। বন্ধুরা, আর আমি তাদের বলব আমার বাবাকে রাখতে। যুদ্ধ একটা সাধারণ নিয়ম। কিন্তু এটা আমাদের মা আর মায়ের মা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْحَمُ أُمَّتِي بِأُمَّتِي ‏ ‏أَبُو بَكْرٍ ‏ ‏وَأَشَدُّهُمْ فِي دِينِ اللَّهِ ‏ ‏عُمَرُ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً فِي أَمْرِ اللَّهِ ‏ ‏عُمَرُ ‏ ‏وَأَصْدَقُهُمْ حَيَاءً ‏ ‏عُثْمَانُ ‏ ‏وَأَفْرَضُهُمْ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏وَأَقْرَؤُهُمْ لِكِتَابِ اللَّهِ ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏وَأَعْلَمُهُمْ بِالْحَلَالِ وَالْحَرَامِ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏أَلَا وَإِنَّ لِكُلِّ أُمَّةٍ أَمِينًا وَإِنَّ أَمِينَ هَذِهِ الْأُمَّةِ ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏أَجْمَعِينَ ‏","","",""],[13480,13480,"","আমরা কথা বলেছিলাম ভুলে যাওয়ার কথা, সে বলবে যতক্ষণ না আমি তাদের বাইরে নিয়ে যেতে দেখি, সে বলবে তুমি জানো না আমি কিসের কথা বলছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَرِدَنَّ الْحَوْضَ عَلَيَّ رِجَالٌ حَتَّى إِذَا رَأَيْتُهُمْ رُفِعُوا إِلَيَّ ‏ ‏فَاخْتُلِجُوا ‏ ‏دُونِي فَلَأَقُولَنَّ يَا رَبِّ أَصْحَابِي أَصْحَابِي فَيُقَالُ إِنَّكَ لَا تَدْرِي مَا ‏ ‏أَحْدَثُوا ‏ ‏بَعْدَكَ ‏","","",""],[13481,13481,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমি খুশি হয়ে যা শুনেছি তা এক সাথে নিয়ে এসেছি। লর্ড প্রার্থনা করেছেন এবং আশ্বস্ত করেছেন যে কে librsers পড়ে আছে। এই জেল থেকে অন্য জায়গায় পড়তে হবে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْعَزِيزِ بْنَ صُهَيْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا فَلَنْ يَلْبَسَهُ فِي الْآخِرَةِ ‏","","",""],[13482,13482,"","আমরা আবেগ নিয়ে কথা বলেছি... ...যে আমরা তোমার গ্রেসের ব্যাপারে ভুলে গেছি, তার কাছে একটা মই আছে, তুমি সমুদ্রের কাছে চমৎকার হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَحَّرُوا فَإِنَّ فِي السُّحُورِ بَرَكَةً ‏","","",""],[13483,13483,"","আমরা একটি কামনা দ্বারা বাপ্তাইজিত হয়েছি যে একটি প্রথা কি ভাবে আপনার নামে একটি ছেলে উপাসনার যে নামে আপনি নামকরণ করা হয়েছে. সে আমার জন্য ভাল জীবন আর আমার আনুগত্য আমার জন্য ভালো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَتَمَنَّى أَحَدُكُمْ الْمَوْتَ مِنْ ضُرٍّ نَزَلَ بِهِ فَإِنْ كَانَ لَا بُدَّ فَاعِلًا فَلْيَقُلْ اللَّهُمَّ أَحْيِنِي مَا كَانَتْ الْحَيَاةُ خَيْرًا لِي وَتَوَفَّنِي إِذَا كَانَتْ الْوَفَاةُ خَيْرًا لِي ‏","","",""],[13484,13484,"","আমরা একটা প্রথা নিয়ে কথা বলেছি... ...আমি তার জন্য প্রার্থনা করেছি, আর সে আমাকে একটা রাগী কথা বলছিল যে আমরা মানুষ। আমি পরামর্শ দিচ্ছি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْعَزِيزِ بْنَ صُهَيْبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُضَحِّي بِكَبْشَيْنِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏وَأَنَا أُضَحِّي بِهِمَا ‏","","",""],[13485,13485,"","আমরা আবেগে বাপ্তাইজিত হয়েছি... ...যে কিনা কিনা তা করতে পারবে না। ঈশ্বর একবার অন্ত্যেষ্টিক্রিয়ার সুযোগ দিয়েছেন, তারপর আমরা তাকে হারিয়েছি। তার কাছে অপরাধী বা অন্য কারো সঙ্গেও গিয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتْ عَلَيْهِ جَنَازَةٌ فَأَثْنَوْا عَلَيْهَا خَيْرًا فَقَالَ وَجَبَتْ وَجَبَتْ وَمَرَّتْ عَلَيْهِ جَنَازَةٌ فَأَثْنَوْا عَلَيْهَا شَرًّا فَقَالَ وَجَبَتْ وَجَبَتْ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ قَوْلُكَ الْأَوَّلُ وَجَبَتْ وَقَوْلُكَ الْآخَرُ وَجَبَتْ قَالَ أَمَّا الْأَوَّلُ فَأَثْنَوْا عَلَيْهَا خَيْرًا فَقُلْتُ وَجَبَتْ لَهُ الْجَنَّةُ وَأَمَّا الْآخَرُ فَأَثْنَوْا عَلَيْهَا شَرًّا فَقُلْتُ وَجَبَتْ لَهُ النَّارُ وَأَنْتُمْ شُهَدَاءُ اللَّهِ فِي أَرْضِهِ ‏","","",""],[13486,13486,"","আমরা এই কামনায় বাপ্তাইজিত হয়েছি যে আমরা প্রভুর মহিমার সবচেয়ে বড় নেকড়েদের বড় বড় বড় বড় কে নিয়ে এসেছি। ঈশ্বর ঈশ্বরের কাছে প্রার্থনা করেছেন, তিনি জানেন এবং জানেন এবং তিনি জানেন এবং আমাদের জন্য প্রার্থনা করেন। সে তাকে একটা ফাঁপা দিতে চেয়েছিল আর নিয়ে যেতে পারত.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُجَوِّزُهَا وَيُكْمِلُهَا ‏ ‏يَعْنِي يُخَفِّفُ الصَّلَاةَ ‏","","",""],[13487,13487,"","আমরা এমন আবেগ নিয়ে কথা বলেছি যা তাদের প্রতিশ্রুতি দিয়েছে যারা বিয়ে করতে ইচ্ছুক। সে এক গ্রীষ্মের মধ্যে দিয়ে দেবে। সে বলেছিল তার সাথে একটা মিল ছিল।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَفِيَّةَ ‏ ‏فَقَالَ لَهُ ‏ ‏ثَابِتٌ ‏ ‏مَا أَصْدَقَهَا قَالَ ‏ ‏أَصْدَقَهَا ‏ ‏نَفْسَهَا أَعْتَقَهَا وَتَزَوَّجَهَا ‏","","",""],[13488,13488,"","আমরা একটি আবেগ দ্বারা বাপ্তাইজিত হয়েছি যে আমরা হয়তো একটি উলের অনুরূপ একটি প্রথা তৈরি করেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি ঈশ্বরের কথার দ্বারা প্রতারিত হবেন প্রতারণা অথবা ডিজিটের প্রতারণার প্রতারণা, সে সবাইকে বলে দিয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى ‏ ‏الْخَلَاءَ ‏ ‏قَالَ أَعُوذُ بِاللَّهِ مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبِيثِ ‏ ‏أَوْ ‏ ‏الْخَبَائِثِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَقَدْ قَالَهُمَا جَمِيعًا ‏","","",""],[13489,13489,"","আমরা ঈশ্বরের দ্বারা উৎপন্ন আবেগ দ্বারা বাপ্তাইজিত হয়েছি, আর তাকেও বলা হয়েছে, সে ঈশ্বরের কাছে প্রার্থনা করতে যাচ্ছে, সে প্রার্থনা করছে এবং সে তোমার নাম জিজ্ঞেস করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ بِخَمْسَةِ ‏ ‏مَكَاكِيكَ ‏ ‏وَكَانَ يَتَوَضَّأُ ‏ ‏بِالْمَكُّوكِ ‏","","",""],[13490,13490,"","আমরা আমার বাবার সাথে কথা বলার চেষ্টা করেছি, এই রহস্যটা প্রভুর মশীহের সাথে আমাদের হত্যা করেছে, কিন্তু আমরা শহরে এসেছি। আপনার ছেলের তৎপরতার জীবন রয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ الصَّلَاةِ فِي السَّفَرِ فَقَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَكُنَّا نُصَلِّي رَكْعَتَيْنِ حَتَّى نَرْجِعَ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَسَأَلْتُهُ كَمْ أَقَمْتُمْ ‏ ‏بِمَكَّةَ ‏ ‏قَالَ عَشَرَةَ أَيَّامٍ قُلْتُ فَبِمَ ‏ ‏أَهَلَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَبَّيْكَ بِعُمْرَةٍ وَحَجَّةٍ ‏","","",""],[13491,13491,"","আমরা একটা প্রথা নিয়ে কথা বলেছি যা আমাকে বলল প্রভু প্রভু, আপনার ছেলেকে একবার বলতে হবে অথবা আল্লাহ্‌র কাছে পৌঁছেছেন। পতাকা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَبَّيْكَ بِعُمْرَةٍ وَحَجَّةٍ مَعًا ‏ ‏أَوْ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13492,13492,"","আমরা গুজবের উপর যে আওয়াজ শুনেছি তা শোনার জন্য আমি তোমার ঋণের কথা শুনেছি। সে বলে, ঈশ্বর তাকে শিখিয়েছেন এবং আমাদের মধ্যে একটি মেঘ আত্মসমর্পন করবে যে তাকে ভাড়া করতে বাধ্য করেছে অথবা যাই হোক, তার শট থেকে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏دَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُلَامًا مِنَّا ‏ ‏فَحَجَمَهُ ‏ ‏فَأَعْطَاهُ أَجْرَهُ ‏ ‏صَاعًا ‏ ‏أَوْ ‏ ‏صَاعَيْنِ ‏ ‏وَكَلَّمَ ‏ ‏مَوَالِيَهُ ‏ ‏أَنْ يُخَفِّفُوا عَنْهُ مِنْ ضَرِيبَتِهِ ‏","","",""],[13493,13493,"","আমরা কামনার সাথে কথা বলেছি, আমরা ইশ্বরের জন্য ঈশ্বরের কাছে পাঠানো শাসনের জন্য ভাল করেছি। কবিতার কিছু এলাকার জন্য মাসব্যাপী আহ্বান জানানো হচ্ছে, আমার ছেলে জীবিত আছে এবং সকাল সকাল বেলা প্রার্থনা করে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏شَهْرًا يَدْعُو عَلَى أَحْيَاءٍ مِنْ ‏ ‏الْعَرَبِ ‏ ‏رِعْلٍ ‏ ‏وَبَنِي لِحْيَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏وَذَكْوَانَ ‏ ‏فِي صَلَاةِ الصُّبْحِ ‏","","",""],[13494,13494,"","আমরা আমাদের আবেগ দিয়ে সিদ্ধান্ত নিয়েছি যে আমরা এত টাকা নিয়ে... ...বন্দুকের অনেক টাকা দিতে ভুলে যেতে পেরে খুশি হয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏شَهْرًا بَعْدَ الرُّكُوعِ ‏","","",""],[13495,13495,"","আমরা আবেগ নিয়ে কথা বলেছি... ...যে আপনারা তোমাদের টাকা ভুলে গেছেন, তার জন্য আমরা তোমাদের হাত বাড়িয়েছি, সে কোন কিছুর জন্য নয়, এমনকি তার পদক্ষেপও দেখেছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَا يَرْفَعُ يَدَيْهِ فِي شَيْءٍ مِنْ الدُّعَاءِ إِلَّا عِنْدَ ‏ ‏الِاسْتِسْقَاءِ ‏ ‏حَتَّى يُرَى بَيَاضُ إِبْطَيْهِ ‏","","",""],[13496,13496,"","আমরা আবেগ দিয়ে বাপ্তাইজিত হয়েছি, যারা ঈশ্বরের কাছে পাঠানো তাদের বিচারের সম্মুখীন হয়েছি। কে ভুলে গেছে বা ঘুমোলো, সে যদি তার কাছে পৌঁছাতে সক্ষম হয়, তাহলে সে তার কাছে পৌঁছাতে সক্ষম হবে। তার নাম বলল.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ نَسِيَ صَلَاةً أَوْ نَامَ عَنْهَا فَإِنَّ كَفَّارَتَهَا أَنْ يُصَلِّيَهَا إِذَا ذَكَرَهَا ‏","","",""],[13497,13497,"","আমরা কিছু সাহস নিয়ে কথা বলেছি যাতে বলে যে ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন আর তাকে দেখতে হবে যে তিনি ভাড়া থেকে অনেক দূরে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏إِنْ كَانَ الْمُؤَذِّنُ لَيُؤَذِّنُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنُرَى أَنَّهَا الْإِقَامَةُ مِنْ كَثْرَةِ مَنْ يَقُومُ فَيُصَلِّي الرَّكْعَتَيْنِ قَبْلَ الْمَغْرِبِ ‏","","",""],[13498,13498,"","আমরা খালি পায়ে হেঁটে সেই ট্যাক্সির কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَمْزَةَ الضَّبِّيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مَا صَلَّيْتُ ‏ ‏يَعْنِي وَرَاءَ رَجُلٍ أَوْ أَحَدٍ مِنْ النَّاسِ ‏ ‏أَخَفَّ صَلَاةً مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي تَمَامٍ ‏","","",""],[13499,13499,"","আমরা এই কামনায় বাপ্তাইজিত হয়েছি যে... ...আমরা তোমার টাকা ভুলে যাওয়ার ঐতিহ্য নিয়ে... ...আমার নিজের রক্ত নিয়ে কাজ করতে হবে, ঈশ্বর তাকে ঐ মহিলাকে আত্মসমর্পণ করতে বলেছেন আমি তাকে ঘুম পাড়িয়েছি, ঈশ্বরের মহান গোলাপের মা, সে আত্মসমর্পণ করবে অথবা সে এটাই বলবে, আমি সাদা, আমি নারী, আমি নারী, আমি একজন ভালো মানুষ। আগে থেকেই ছিল বা কে রাজা ছিল.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ أُمَّهُ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏سَأَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏الْمَرْأَةُ ‏ ‏تَرَى فِي مَنَامِهَا مَا يَرَى الرَّجُلُ فَقَالَ إِذَا رَأَتْ ذَلِكَ فِي مَنَامِهَا فَلْتَغْتَسِلْ فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْتَحْيَتْ أَوَيَكُونُ هَذَا يَا رَسُولَ اللَّهِ قَالَ نَعَمْ فَمِنْ أَيْنَ يَكُونُ الشَّبَهُ ‏ ‏مَاءُ ‏ ‏الرَّجُلِ أَبْيَضُ غَلِيظٌ ‏ ‏وَمَاءُ ‏ ‏الْمَرْأَةِ أَصْفَرُ رَقِيقٌ فَمِنْ أَيِّهِمَا سَبَقَ ‏ ‏أَوْ عَلَا ‏ ‏يَكُونُ الشَّبَهُ ‏","","",""],[13500,13500,"","আমরা তোমার ঝামেলা ভুলে যাওয়ার কথা বলেছিলাম, আমার চাচা ঈশ্বরের বার্তাবাহকের সাথে মারা যাচ্ছে, তার কলম তাকে মারার অপেক্ষায় আছে। আমাকে কখনোই বলতে হবে না খোদা আমার ছেলে, আমি দুঃখিত বা না যাচ্ছি ঈশ্বরের কাছে যা বলবো তা না করতে যে এটা অনেক বেশি সেক্স।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏انْطَلَقَ ‏ ‏حَارِثَةُ ‏ ‏ابْنُ عَمَّتِي يَوْمَ ‏ ‏بَدْرٍ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُلَامًا ‏ ‏نَظَّارًا ‏ ‏مَا انْطَلَقَ لِلْقِتَالِ قَالَ فَأَصَابَهُ سَهْمٌ فَقَتَلَهُ قَالَ فَجَاءَتْ ‏ ‏أُمُّهُ ‏ ‏عَمَّتِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ابْنِي ‏ ‏حَارِثَةُ ‏ ‏إِنْ يَكُنْ فِي الْجَنَّةِ أَصْبِرْ وَأَحْتَسِبْ وَإِلَّا ‏ ‏فَسَيَرَى اللَّهُ مَا أَصْنَعُ قَالَ يَا ‏ ‏أُمَّ حَارِثَةَ ‏ ‏إِنَّهَا جِنَانٌ كَثِيرَةٌ وَإِنَّ ‏ ‏حَارِثَةَ ‏ ‏فِي ‏ ‏الْفِرْدَوْسِ ‏ ‏الْأَعْلَى ‏","","",""],[13501,13501,"","আমরা তোমার লড়াই নিয়ে কথা বলেছি কিন্তু আমরা এটা নিয়ে কথা বলেছি। ঈশ্বর তাঁর কোর্টে পৌঁছে দিয়েছেন, এবং হঠাৎ করে একজন মানুষ ঈশ্বরের কাছে সাহায্যের জন্য প্রার্থনা করার সময়, ঈশ্বর, আমি তার গণনা করতে চাই না। সে বলল, সে তার পিতাকে প্রার্থনা করে এবং সে তার ছেলেকে ফোন করে যখন সে বলেছিল যে সে ছিল সেই সেই ব্যক্তি, যে ছিল সেই ব্যক্তি, যে কিনা সেই লোক। তিনিই সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি । ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর রক্তের এক মেঘ যদি তাঁর ওপর থেকে থাকে, তা হলে তিনি প্রভু ঈশ্বরের কাছে প্রার্থনা করেছেন । তিনি আরও বলেছিলেন যে, লোকেরা আমার গ্রাম থেকে ঘুমিয়ে আছে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُبَارَكُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِهِ فَجَاءَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ قَالَ ‏ ‏أَمَا إِنَّهَا قَائِمَةٌ فَمَا أَعْدَدْتَ لَهَا قَالَ وَاللَّهِ يَا رَسُولَ اللَّهِ مَا أَعْدَدْتُ لَهَا مِنْ كَثِيرِ عَمَلٍ غَيْرَ أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ فَإِنَّكَ مَعَ مَنْ أَحْبَبْتَ وَلَكَ مَا ‏ ‏احْتَسَبْتَ ‏ ‏قَالَ ثُمَّ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فَلَمَّا قَضَى صَلَاتَهُ قَالَ أَيْنَ السَّائِلُ عَنْ السَّاعَةِ فَأُتِيَ بِالرَّجُلِ فَنَظَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْبَيْتِ فَإِذَا ‏ ‏غُلَامٌ ‏ ‏مِنْ ‏ ‏دَوْسٍ ‏ ‏مِنْ ‏ ‏رَهْطِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يُقَالُ لَهُ ‏ ‏سَعْدُ بْنُ مَالِكٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا الْغُلَامُ إِنْ طَالَ بِهِ عُمُرٌ لَمْ يَبْلُغْ بِهِ ‏ ‏الْهَرَمُ ‏ ‏حَتَّى تَقُومَ السَّاعَةُ ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏وَأَخْبَرَنِي ‏ ‏أَنَسٌ ‏ ‏أَنَّ الْغُلَامَ كَانَ يَوْمَئِذٍ مِنْ ‏ ‏أَقْرَانِي ‏","","",""],[13502,13502,"","আমরা তাকে তোমার ব্যাপারে জানতে সাহায্য করার কথা বলেছিলাম, ঈশ্বর বলেছেন তোমার প্রভু জিতে গেছেন আর আমার নিয়ন্ত্রণের বাইরে চলে যাবে। তুমি জানো আমি একটু ক্লান্ত, আর যদি তুমি আমাকে নিয়ে চিন্তা কর, আমি জানি, এটা নিয়ে চলে যাও।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ أَبُو إِسْمَاعِيلَ الْقَنَّادُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْوِيهِ عَنْ رَبِّهِ عَزَّ وَجَلَّ قَالَ يَقُولُ رَبُّكُمْ عَزَّ وَجَلَّ ‏ ‏إِذَا ‏ ‏تَلَقَّانِي ‏ ‏عَبْدِي شِبْرًا تَلَقَّيْتُهُ ذِرَاعًا وَإِذَا ‏ ‏تَلَقَّانِي ‏ ‏ذِرَاعًا تَلَقَّيْتُهُ ‏ ‏بَاعًا ‏ ‏وَإِذَا ‏ ‏تَلَقَّانِي ‏ ‏يَمْشِي تَلَقَّيْتُهُ ‏ ‏أُهَرْوِلُ ‏","","",""],[13503,13503,"","আমরা আমার ভালবাসার কথা ভুলে গিয়েছিলাম, সে বলল আমি নরক বা পরিবর্তনের কাজ করছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي الْعَطَّارَ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بُعِثْتُ أَنَا وَالسَّاعَةُ كَهَاتَيْنِ ‏ ‏وَأَوْمَأَ ‏ ‏عَفَّانُ ‏ ‏بِالسَّبَّابَةِ وَالْوُسْطَى ‏","","",""],[13504,13504,"","আমরা তোমাকে হত্যা করার কথা বলেছিলাম, আমরা তোমার টাকা ভুলে খারাপ ছেলের কথা বলেছিলাম । অপরাধী, আর যদি সে পালিয়ে যেতে চায়,","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏حَارِثَةُ ‏ ‏أُصِيبَ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ حَارِثَةَ ‏ ‏يَا نَبِيَّ اللَّهِ إِنْ كَانَ ابْنِي ‏ ‏أَصَابَ ‏ ‏الْجَنَّةَ وَإِلَّا أَجْهَدْتُ عَلَيْهِ بِالْبُكَاءِ قَالَ يَا ‏ ‏أُمَّ حَارِثَةَ ‏ ‏إِنَّهَا جِنَانٌ كَثِيرَةٌ فِي جَنَّةٍ وَإِنَّ ‏ ‏حَارِثَةَ ‏ ‏أَصَابَ ‏ ‏الْفِرْدَوْسَ ‏ ‏الْأَعْلَى ‏","","",""],[13505,13505,"","আমার বাবা বলেছেন এটা হচ্ছে বন্ধন আর ঈশ্বরের দোহাইের কসমটা অটুট আছে। আর ঈশ্বরের দাস হওয়া আর ঈশ্বরের দাস হওয়া।","‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَبِهَذَا الْإِسْنَادِ وَاللَّفْظِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا تَبَاغَضُوا وَلَا تَحَاسَدُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[13506,13506,"","তিনি আমার সাথে কথা বলেছিলেন এবং বলেছিলেন যে ভাববাদী তার কাছে প্রার্থনা করেছেন এবং তিনি বলবেন আপনি একমাত্র বিশ্বের মতো আবদ্ধ হবেন। আলিঙ্গনটা আমাদের এতো দৃঢ় করে যে আমরা তার দ্বারা স্থির থাকি। হাত দিয়ে আমি দেখছি সব পশমের সংকেত থেকে শয়তান প্রবেশ করেছে.","‏ ‏حَدَّثَنِي ‏ ‏قَالَ ‏ ‏وَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏تَرَاصُّوا صُفُوفَكُمْ وَقَارِبُوا بَيْنَهَا ‏ ‏وَحَاذُوا ‏ ‏بَيْنَ الْأَعْنَاقِ فَوَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ إِنِّي لَأَرَى الشَّيْطَانَ يَدْخُلُ مِنْ ‏ ‏خَلَلِ ‏ ‏الصَّفِّ كَأَنَّهُ ‏ ‏الْحَذَفُ ‏","","",""],[13507,13507,"","আমরা আমাদের সময় জয়ের কথা বলেছিলাম, নিজের টাকা ভুলে গিয়ে ঈশ্বরের কাছে ফিরে যাওয়া ভুলে যাওয়ার কথা। সে বলবে যে ঈশ্বর জিতে গেছেন এবং তাকে আরও ভাল এক বছরের জন্য বিশ্বস্ত থাকবেন না। আমি অবাক হয়ে যাচ্ছি, আর সব কিছুর জন্য ভালোর জন্য। বড়দের দেনা হয়ে যায়, এমনকি যদি আমি শেষ পর্যন্ত তার কাছে একটা লাইন না পাই।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَظْلِمُ الْمُؤْمِنَ حَسَنَةً يُثَابُ عَلَيْهَا الرِّزْقَ فِي الدُّنْيَا ‏ ‏وَيُجْزَى بِهَا فِي الْآخِرَةِ قَالَ وَأَمَّا الْكَافِرُ فَيُطْعَمُ بِحَسَنَاتِهِ فِي الدُّنْيَا حَتَّى إِذَا ‏ ‏أَفْضَى ‏ ‏إِلَى الْآخِرَةِ لَمْ يَكُنْ لَهُ حَسَنَةٌ يُعْطَى بِهَا خَيْرًا ‏","","",""],[13508,13508,"","আমরা তোমার টাকা নিয়ে ভুলে গেছি, আমরা তাকে যুদ্ধ করতে বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏بِبَرَاءَةٌ ‏ ‏مَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏قَالَ ثُمَّ دَعَاهُ فَبَعَثَ بِهَا ‏ ‏عَلِيًّا ‏ ‏قَالَ ‏ ‏لَا يُبَلِّغُهَا إِلَّا رَجُلٌ مِنْ أَهْلِي ‏","","",""],[13509,13509,"","আমরা আমার বাবার কথা বলেছিলাম তুমি তোমার টাকা ভুলে যাবে। ঈশ্বর তার কাছে প্রার্থনা করেছিলেন আর আত্মসমর্পণ করলেন তুমি মানুষের শিকারে কাউকে দেখতেও পাবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى ‏ ‏يَتَبَاهَى النَّاسُ فِي الْمَسَاجِدِ ‏","","",""],[13510,13510,"","আমরা আমাদের নিজের লোকদের খুঁজে বের করার কথা বলেছিলাম। ঈশ্বর বলেছেন, \"তুমি যাবে না, তারপর আবার ঘটনা ঘটল।\"","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ قَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْعَثُ بْنُ جَابِرٍ الْحَدَّانِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ رَبُّكُمْ عَزَّ وَجَلَّ ‏ ‏مَنْ أَذْهَبْتُ كَرِيمَتَيْهِ ثُمَّ صَبَرَ ‏ ‏وَاحْتَسَبَ ‏ ‏كَانَ ثَوَابُهُ الْجَنَّةَ ‏","","",""],[13511,13511,"","আমি যখন তোমার সম্বন্ধে ভুলে গিয়েছিলাম, তখন আমরা সেই বিষয়টা নিয়ে কথা বলতাম । প্রার্থনা করছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏قِرَامٌ ‏ ‏لِعَائِشَةَ ‏ ‏قَدْ سَتَرَتْ بِهِ جَانِبَ بَيْتِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمِيطِي ‏ ‏قِرَامَكِ ‏ ‏هَذَا عَنِّي فَإِنَّهُ لَا يَزَالُ تَصَاوِيرُهُ تَعْرِضُ لِي فِي صَلَاتِي ‏","","",""],[13512,13512,"","আমরা ভুলে যাওয়ার কথা বলেছিলাম, ঈশ্বর তাকে শিখিয়েছিলেন আর তারা আমাকে ঈশ্বরের কাছে শপথ করে বলবে, আমি তোমাকে কোয়ার্টার থেকে বলছি","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ خَلِيفَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ مِنْ دُعَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَقَلْبٍ لَا يَخْشَعُ وَدُعَاءٍ لَا يُسْمَعُ وَنَفْسٍ لَا تَشْبَعُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ هَؤُلَاءِ الْأَرْبَعِ ‏","","",""],[13513,13513,"","আমরা আমাদের আলোচনা এমন এক দিনে আটকে রাখা হয়েছে, যা তোমার টাকা ভুলে যাওয়ার চেয়ে আমার কাছে অনেক ভালো ছিল। মাত্র তিনবার তাকে ছেড়ে গেল, সে আর তাকে মারতে পারবে না। তার প্রথম বিয়ে বলল, ঈশ্বর তার কাছে প্রার্থনা করেছেন যেন সে তার কাছে আত্মসমর্পণ করে। শেষ জন যে, সেই একের পর এক যে কিনা একের পর এক হওয়া সম্ভব ( ১ যোহন ৫: ১৯) তাই, একজন ব্যক্তিই হলেন সেই ব্যক্তি, যিনি দোষ ধরার জন্য দায়ী ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ دِينَارٍ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ رَجُلٍ كَانَتْ تَحْتَهُ امْرَأَةٌ فَطَلَّقَهَا ثَلَاثًا فَتَزَوَّجَتْ بَعْدَهُ رَجُلًا فَطَلَّقَهَا قَبْلَ أَنْ يَدْخُلَ بِهَا أَتَحِلُّ لِزَوْجِهَا الْأَوَّلِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا حَتَّى يَكُونَ الْآخَرُ قَدْ ذَاقَ مِنْ ‏ ‏عُسَيْلَتِهَا ‏ ‏وَذَاقَتْ مِنْ ‏ ‏عُسَيْلَتِهِ ‏","","",""],[13514,13514,"","আমি বলেছিলাম, আমরা যদি ঈশ্বরের কাছে প্রার্থনা করি, তাহলে কি করে এর সমাধান করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏جَعْفَرُ بْنُ مَعْبَدٍ ‏ ‏قَالَ ‏ ‏ذَهَبْتُ إِلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَا ‏ ‏وَحُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ فَسَمِعْتُ ‏ ‏أَنَسًا ‏ ‏قَالَ كُنَّا ‏ ‏إِذَا ‏ ‏بَايَعْنَا ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَقِّنُنَا هُوَ فِيمَا اسْتَطَعْتَ ‏","","",""],[13515,13515,"","আমরা বাবার সাথে তার জেদের কথা বলেছিলাম... ...তার কথায় বাবার জেদের কথা যা শুনেছি, তা নিয়ে আমার বাবার জেদের কথা। \"আমি শুনেছি\" আল্লাহ্‌কে আত্মসমর্পণ করতে হবে যদি তাকে যেতে হয়। তাকে আমাদের একজন সন্তান হিসেবে চলতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مُعَاذٍ عَطَاءِ بْنِ أَبِي مَيْمُونٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ ‏ ‏لِحَاجَتِهِ ‏ ‏نَجِيءُ أَنَا وَغُلَامٌ مِنَّا ‏ ‏بِإِدَاوَةٍ ‏ ‏مِنْ مَاءٍ ‏","","",""],[13516,13516,"","আমি আমার ভাই কে নিয়ে কথা বলেছিলাম যে আমাকে ভয় পেতে হবে. তার হাত ডাকো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْرَائِيلَ ‏ ‏سَأَلْتُ أَبِي عَنْهُ فَقَالَ ‏ ‏شَيْخٌ ثِقَةٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو إِسْحَاقَ يَعْنِي الْفَزَارِيَّ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏بَعَثَتْنِي أُمِّي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَيْءٍ فَرَأَيْتُهُ ‏ ‏قَائِمًا فِي يَدِهِ ‏ ‏الْمِيسَمُ ‏ ‏يَسِمُ ‏ ‏الصَّدَقَةَ ‏","","",""],[13517,13517,"","আমরা সেই বাপ্তিস্মের কথা বলেছিলাম, আমাদেরকে প্রভুর বোনদের কথা বলতে হয়েছে। তারা ঈশ্বরের কাছে ঈশ্বরকে পাঠাতে বলেছিল এবং ঈশ্বর বলে যে, তিনি তাকে উদ্ধার করতে বলেছেন। ঈশ্বর ঈশ্বর বলেছেন, ঈশ্বর তাঁর কাছে যা লিখেছেন, তা হলো, ঈশ্বর যা লিখেছেন, সেই ই হোক। আল্লাহ কখনো ভেঙ্গে দেননি। ধর্ম মেনে নিয়েছে যে তিনি প্রভুর কাছে প্রার্থনা করেছেন। ঈশ্বরের দোহাই লাগে ভগবানের ভগবানের কসম... ...যে তার কাছে শপথ করত.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ أُخْتَ ‏ ‏الرُّبَيِّعِ أُمَّ حَارِثَةَ ‏ ‏جَرَحَتْ إِنْسَانًا ‏ ‏فَاخْتَصَمُوا ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقِصَاصُ ‏ ‏الْقِصَاصُ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ الرُّبَيِّعِ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏أَيُقْتَصُّ ‏ ‏مِنْ فُلَانَةَ لَا وَاللَّهِ لَا ‏ ‏يُقْتَصُّ ‏ ‏مِنْهَا أَبَدًا قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَانَ اللَّهِ يَا ‏ ‏أُمَّ رُبَيِّعٍ ‏ ‏كِتَابُ اللَّهِ قَالَتْ لَا وَاللَّهِ لَا ‏ ‏يُقْتَصُّ ‏ ‏مِنْهَا أَبَدًا قَالَ فَمَا زَالَتْ حَتَّى قَبِلُوا مِنْهَا ‏ ‏الدِّيَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ عِبَادِ اللَّهِ مَنْ لَوْ أَقْسَمَ عَلَى اللَّهِ ‏ ‏لَأَبَرَّهُ ‏","","",""],[13518,13518,"","আমরা মসজিদ নিয়ে কথা বলেছি, আমরা জানতে চাই কে লর্ডকে এটা সমাধান করতে বলবে। আমি তাকে একটা গান দিয়েছিলাম। দুই বছর আগে তাকে বলা হয়েছিল যে তিনি কি বলছেন। যদি লোকটা ঈশ্বরের কাছে এসে তাকে ছেড়ে দিত, সে আমাকে আত্মসমর্পণ করতো, নাহলে আমি সেটা গর্ত থেকে ফেলে দিতাম.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْطَاهُ غَنَمًا بَيْنَ جَبَلَيْنِ فَأَتَى قَوْمَهُ فَقَالَ أَيْ قَوْمِ أَسْلِمُوا فَوَاللَّهِ ‏ ‏إِنَّ ‏ ‏مُحَمَّدًا ‏ ‏لَيُعْطِي عَطَاءَ مَنْ لَا يَخَافُ ‏ ‏الْفَاقَةَ ‏ ‏وَإِنْ كَانَ الرَّجُلُ لَيَجِيءُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يُرِيدُ إِلَّا الدُّنْيَا فَمَا يُمْسِي حَتَّى يَكُونَ دِينُهُ أَحَبَّ إِلَيْهِ ‏ ‏أَوْ أَعَزَّ عَلَيْهِ ‏ ‏مِنْ الدُّنْيَا بِمَا فِيهَا ‏","","",""],[13519,13519,"","আমরা এটা ভুলে গিয়েছিলাম যে, ঈশ্বর এসে গেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حُفَّتْ ‏ ‏الْجَنَّةُ بِالْمَكَارِهِ ‏ ‏وَحُفَّتْ ‏ ‏النَّارُ بِالشَّهَوَاتِ ‏","","",""],[13520,13520,"","আমরা ভুলে গিয়েছিলাম যে ঈশ্বর এসে গেছেন, সে একটা দেয়ালে একটা কুঁড়েঘরে গিয়ে গেছে আর সে চলে যাচ্ছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন আর যদি তুমি আত্মসমর্পণ করো তাহলে আমি তোমাকে আত্মসমর্পণ করবো উত্তর দিতে ব্যর্থ হবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِمَقْبَرَةٍ ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏فِي ‏ ‏حَائِطٍ ‏ ‏وَهُوَ عَلَى بَغْلَةٍ ‏ ‏شَهْبَاءَ ‏ ‏فَإِذَا هُوَ بِقَبْرٍ يُعَذَّبُ ‏ ‏فَحَاصَتْ ‏ ‏الْبَغْلَةُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَسَأَلْتُ اللَّهَ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ ‏","","",""],[13521,13521,"","আমরা এমন লোকদের বেছে নিতে বলেছিলাম যারা তার কাছে গিয়েছিল আর বাবা বলেছে ঈশ্বর জিতে গেছেন আর আমি যা বলেছি তা তোমাদের সামনে আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا ‏ ‏أُبَيًّا ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ أَمَرَنِي أَنْ أَقْرَأَ عَلَيْكَ فَقَالَ سَمَّانِي لَكَ فَقَالَ اللَّهُ سَمَّاكَ لِي فَجَعَلَ يَبْكِي ‏","","",""],[13522,13522,"","আমরা ইশ্বরের কাছে প্রার্থনা করেছিলাম তার জন্য প্রার্থনা না করে, সে মারা যাওয়ার জন্য আমরা দুঃখিত, ঈশ্বর তার ধর্ম ফিরে পেয়ে খুশি। ছায়া.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ نَفْسٍ ‏ ‏مَنْفُوسَةٍ ‏ ‏تَمُوتُ لَهَا عِنْدَ اللَّهِ خَيْرٌ يَسُرُّهَا أَنْ تَرْجِعَ إِلَى الدُّنْيَا إِلَّا الشَّهِيدَ فَإِنَّهُ يَسُرُّهُ أَنْ يَرْجِعَ إِلَى الدُّنْيَا فَيُقْتَلَ لِمَا يَرَى مِنْ فَضْلِ الشَّهَادَةِ ‏","","",""],[13523,13523,"","আমরা ঈশ্বরের দোহাই দিয়ে কথা বলেছি যারা ঈশ্বরের দোহাইের সাথে প্রার্থনা করতে হয়েছে. যে লোকটা আমার থেকে এসেছে আর তারা আগুনের ডিপার্টমেন্টে হাঁটু গেড়ে বসে আছে হয়তো অন্ধকার পর্যন্ত, সে তারা যে টাকা তারা তারা ছিল তা খেলত চুমু খেতে পছন্দ করি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي نَحْوَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏فَنَزَلَتْ ‏ { ‏قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا فَوَلِّ وَجْهَكَ شَطْرَ ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ } ‏فَمَرَّ رَجُلٌ مِنْ ‏ ‏بَنِي سَلَمَةَ ‏ ‏وَهُمْ رُكُوعٌ فِي صَلَاةِ الْفَجْرِ وَقَدْ صَلَّوْا رَكْعَةً فَنَادَى أَلَا إِنَّ الْقِبْلَةَ قَدْ حُوِّلَتْ أَلَا إِنَّ الْقِبْلَةَ قَدْ حُوِّلَتْ إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏قَالَ فَمَالُوا كَمَا هُمْ نَحْوَ الْقِبْلَةِ ‏","","",""],[13524,13524,"","আমরা ভুলে গিয়েছিলাম যে ঈশ্বর এটা জিজ্ঞেস করবেন। সে বলল, অপরাধী তার শরীরে তার প্রতিটি দলই তোমার এই রকমে আছে, যাতে তারা তাকে হারাতে পারে। আমি অনুমান করি সে মনে করে যে সে এটা ভুলে যাবে। তাদের মুখ পূর্ণ করতে বলা হয়েছে, তাদের মন আর হৃদয় ঠিক আছে, সবাই বলে তারা ভালো আছে, তারপর আমরা ঠিক থাকবো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِأَهْلِ الْجَنَّةِ سُوقًا ‏ ‏يَأْتُونَهَا كُلَّ جُمُعَةٍ فِيهَا ‏ ‏كُثْبَانُ ‏ ‏الْمِسْكِ ‏ ‏فَإِذَا خَرَجُوا إِلَيْهَا هَبَّتْ الرِّيحُ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَحْسِبُهُ قَالَ شَمَالِيٌّ ‏ ‏قَالَ فَتَمْلَأُ وُجُوهَهُمْ وَثِيَابَهُمْ وَبُيُوتَهُمْ مِسْكًا فَيَزْدَادُونَ حُسْنًا وَجَمَالًا قَالَ فَيَأْتُونَ أَهْلِيهِمْ فَيَقُولُونَ لَقَدْ ازْدَدْتُمْ بَعْدَنَا حُسْنًا وَجَمَالًا وَيَقُولُونَ لَهُنَّ وَأَنْتُمْ قَدْ ازْدَدْتُمْ بَعْدَنَا حُسْنًا وَجَمَالًا ‏","","",""],[13525,13525,"","আমরা তোমার টাকা ভুলের কথা বলেছিলাম যখন আমরা বিয়ে করিনি। এমনকি তুমি যেভাবে বলছো তা ভেঙেছ, আমার বাবা একটা অন্ধকার, প্রভু আমাদের জিজ্ঞেস করছে আমি কে। আমি খুশি যে, তিনি আমাদের সাহায্য করবেন। আমার বাবা সবসময় বলে চলে চলেছিলেন যে তিনি রক্ষা পেয়েছেন । স্বস্তি পাওয়া এবং আরামদায়ক নয়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏لَنْ تَنَالُوا ‏ ‏الْبِرَّ ‏ ‏حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ ‏} ‏قَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَا رَسُولَ اللَّهِ أَرَى رَبَّنَا يَسْأَلُنَا مِنْ أَمْوَالِنَا وَإِنِّي أُشْهِدُكَ أَنِّي قَدْ جَعَلْتُ أَرْضِي ‏ ‏بَيْرُحَاءَ ‏ ‏لِلَّهِ عَزَّ وَجَلَّ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْعَلْهَا فِي قَرَابَتِكَ فَقَسَمَهَا بَيْنَ ‏ ‏حَسَّانَ بْنِ ثَابِتٍ ‏ ‏وَأُبَيِّ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏بَرِيحَا ‏ ‏و قَالَ ‏ ‏عَفَّانُ ‏ ‏سَأَلْتُ عَنْهَا غَيْرَ وَاحِدٍ مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏فَزَعَمُوا أَنَّهَا ‏ ‏بَيْرُحَاءُ ‏ ‏وَأَنَّ ‏ ‏بَيْرَحَا ‏ ‏لَيْسَ بِشَيْءٍ ‏","","",""],[13526,13526,"","আমি যখন ঘরে ঘরে প্রচারে যেতাম, তখন আমি আমার পরিবারের সঙ্গে কথা বলতাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامُ أَبُو الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُبِّبَ إِلَيَّ مِنْ الدُّنْيَا النِّسَاءُ وَالطِّيبُ وَجُعِلَتْ ‏ ‏قُرَّةُ ‏ ‏عَيْنِي فِي الصَّلَاةِ ‏","","",""],[13527,13527,"","বিদায় বলার পর বাবার খোঁজের ব্যাপারে আমরা কথা বলেছিলাম, সে তার সাথে কথা বলেছে, বাছা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْجَعْدِ أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏يَا بُنَيَّ ‏","","",""],[13528,13528,"","আমরা আমাদের আলোচনা নিয়ে কথা বলেছি আপনি বলছেন যে পৃথিবী চলে গেছে। আমি বিশ্বাস করি আপনি কবিতার মাধ্যমে ঈশ্বর এসে পৌঁছেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏إِنِّي لَأَعْرِفُ الْيَوْمَ ذُنُوبًا هِيَ أَدَقُّ فِي أَعْيُنِكُمْ مِنْ الشَّعْرِ كُنَّا نَعُدُّهَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْكَبَائِرِ ‏","","",""],[13529,13529,"","আমরা আপনার টাকা নিয়ে কথা বলেছি তিনি কখনোই তাকে যেতে দিবেন না। বসরা বাড়িতে গিয়ে রান্না করে রান্না করে","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَمُرُّ بِبَابِ ‏ ‏فَاطِمَةَ ‏ ‏سِتَّةَ أَشْهُرٍ إِذَا خَرَجَ إِلَى صَلَاةِ الْفَجْرِ يَقُولُ ‏ ‏الصَّلَاةُ يَا أَهْلَ الْبَيْتِ ‏ { ‏إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمْ ‏ ‏الرِّجْسَ ‏ ‏أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا ‏}","","",""],[13530,13530,"","আমরা আমাদের প্রভুর বাপ্তিস্মের কথা বলেছি। ভগবান তার কাছে প্রার্থনা করেছেন। আর আমি বলবো যে সে আগুন থেকে বেরিয়ে আসবে। সে বলছে যে সে যুদ্ধ করতে পারবে। তারা ঈশ্বরের কাছে আর ঈশ্বরের কাছে। তারা যদি সত্যিই এগিয়ে যায়, তাহলে আমরা কি করতে পারি? তাহলে আমাকে যেতে হবে এবং বলতে হবে তাদের মধ্যে একজন মারা যাবে, আমি আর তার কাছে ফিরে যাব না, ঈশ্বর তার উপর এক স্তর ভেঙ্গে ফেলেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏وَأَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَخْرُجُ أَرْبَعَةٌ مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏أَبُو عِمْرَانَ ‏ ‏أَرْبَعَةٌ ‏ ‏قَالَ ‏ ‏ثَابِتٌ ‏ ‏رَجُلَانِ ‏ ‏فَيُعْرَضُونَ عَلَى اللَّهِ عَزَّ وَجَلَّ ثُمَّ يُؤْمَرُ بِهِمَا إِلَى النَّارِ قَالَ فَيَلْتَفِتُ أَحَدُهُمْ فَيَقُولُ أَيْ رَبِّ قَدْ كُنْتُ أَرْجُو إِذَا أَخْرَجْتَنِي مِنْهَا أَنْ لَا تُعِيدَنِي فِيهَا ‏ ‏فَيُنْجِيهِ اللَّهُ مِنْهَا عَزَّ وَجَلَّ ‏","","",""],[13531,13531,"","সেই ছেলের সম্বন্ধে আমরা বলেছিলাম যে, কোথায় তাকে বলা হয়েছে । আমি যাকে জিজ্ঞেস করলাম সে কে ছিল, আমি সেটা ভাবতেও পারিনি যে তুমি বলেছিলে যে শয়তান একটা ছেলের কাছ থেকে পালিয়ে বেড়াচ্ছে যে জেলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ ‏ ‏امْرَأَةٍ مِنْ نِسَائِهِ ‏ ‏إِذْ مَرَّ بِهِ رَجُلٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا فُلَانُ هَذِهِ فُلَانَةُ زَوْجَتِي فَقَالَ الرَّجُلُ يَا رَسُولَ اللَّهِ مَنْ كُنْتُ أَظُنُّ بِهِ فَإِنِّي لَمْ أَكُنْ لِأَظُنَّ بِكَ قَالَ ‏ ‏إِنَّ الشَّيْطَانَ يَجْرِي مِنْ ابْنِ ‏ ‏آدَمَ ‏ ‏مَجْرَى الدَّمِ ‏","","",""],[13532,13532,"","আমরা তোমার টাকা ভুলের কথা বলেছিলাম, ভাববাদী এমন কিছু করেছিলেন, তুমি আশা করছ সে ছেলে হবে, প্রার্থনা করবে এবং মরণ করবে ঈশ্বরকে আমি ভালোবাসি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقْبَلَهُ ذَاتَ يَوْمٍ صِبْيَانُ ‏ ‏الْأَنْصَارِ ‏ ‏وَالْإِمَاءُ ‏ ‏فَقَالَ وَاللَّهِ ‏ ‏إِنِّي لَأُحِبُّكُمْ ‏","","",""],[13533,13533,"","আমরা আপনার টাকা ভুলে যে, ছেলেটি এটা করেছে তা ভুলে যাওয়ার কথা বলেছিলাম। ঈশ্বর যখন ভবিষ্যদ্বাণীর সাথে জড়িয়ে ধরেন... ...তখন \"ঈশ্বর আপনাকে উদ্ধার করে দেন, মিস্টার রুর দেওয়া হবে.\"","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ لَهُ ‏ ‏حَادٍ ‏ ‏جَيِّدُ ‏ ‏الْحُدَاءِ ‏ ‏وَكَانَ ‏ ‏حَادِيَ ‏ ‏الرِّجَالِ وَكَانَ ‏ ‏أَنْجَشَةُ ‏ ‏يَحْدُو ‏ ‏بِأَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا ‏ ‏حَدَا ‏ ‏أَعْنَقَتْ الْإِبِلُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْحَكَ ‏ ‏يَا ‏ ‏أَنْجَشَةُ ‏ ‏رُوَيْدًا سَوْقَكَ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[13534,13534,"","আমরা একটা স্বপ্নের কথা বলেছিলাম যারা আমার প্রেমে ভেঙ্গে পড়েছে, ঈশ্বরের কাছে প্রার্থনা করেছে, আমি নবীকে তার কাছে প্রার্থনা করব এবং তাকে গোপনভাবে বলার জন্য তাকে সাহায্য করব তাদের মধ্যে কেউ কেউ বলে আমি ব্যাটে ঘুমাতে যাই নি। তাদের মধ্যে কেউ কেউ বলে আমি বসে বসে বসে বসে যাই। কাজেই আমি প্রার্থনা করি এবং ঘুমিয়ে পড়ি এবং আমি বিভ্রান্ত হয়ে পড়ি। যে সকল নারীকে বিয়ে করবে তারা মারা যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏نَفَرًا ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلُوا أَزْوَاجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ عَمَلِهِ فِي السِّرِّ فَقَالَ بَعْضُهُمْ لَا أَتَزَوَّجُ النِّسَاءَ وَقَالَ بَعْضُهُمْ لَا آكُلُ اللَّحْمَ وَقَالَ بَعْضُهُمْ لَا أَنَامُ عَلَى فِرَاشٍ وَقَالَ بَعْضُهُمْ أَصُومُ وَلَا أُفْطِرُ فَقَامَ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ مَا بَالُ أَقْوَامٍ قَالُوا كَذَا وَكَذَا وَلَكِنِّي ‏ ‏أُصَلِّي وَأَنَامُ وَأَصُومُ وَأُفْطِرُ وَأَتَزَوَّجُ النِّسَاءَ فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي ‏","","",""],[13535,13535,"","আমরা কথা বলেছিলাম কেউ একজন তাকে খুন করেছে, কিন্তু সে বলেছিল, আমাকে বলতে হবে, মা, তুমি তার সাথে যেভাবে কাজ করেছ, তার প্রয়োজনের আগেই তাকে সেটা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ امْرَأَةً كَانَ فِي ‏ ‏عَقْلِهَا ‏ ‏شَيْءٌ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي حَاجَةً فَقَالَ يَا أُمَّ فُلَانٍ انْظُرِي إِلَى أَيِّ الطَّرِيقِ شِئْتِ ‏ ‏فَقَامَ مَعَهَا ‏ ‏يُنَاجِيهَا ‏ ‏حَتَّى قَضَتْ حَاجَتَهَا ‏","","",""],[13536,13536,"","আমরা মানুষের উপর হার্টের আক্রমণ সম্পর্কে কথা বলেছি যারা বলেছিল যখন সে এটা তৈরি করেনি, তখন আমরা কথা বলেছি। আকাশ এত উজ্জ্বল নয় যে, সে পৃথিবীর সেরা। সে বলতে পারত যে, তার একজন লোক ছিল যিনি তাকে এখানে একটা ছাত্র হিসেবে উল্লেখ করেছিলেন আর একবার তাকে বলেছিলেন যে, সে এমন একজন মানুষ যাকে মানুষ হিসেবে চিহ্নিত করা হয়েছে। এমন একজন মানুষ ছিলেন যে এমন একজন মানুষ ছিল যে এমন একজন মানুষ ছিল যে ছেলে ছিল যে ছেলে ছিল, যে কিনা পুত্র ছিল। ( ক) কেন আমাদের ঈশ্বরের প্রতি অনুগত থাকা উচিত?","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنَّا نَتَحَدَّثُ أَنَّهُ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى لَا تُمْطِرَ السَّمَاءُ وَلَا تُنْبِتَ الْأَرْضُ وَحَتَّى يَكُونَ لِخَمْسِينَ امْرَأَةً ‏ ‏الْقَيِّمُ ‏ ‏الْوَاحِدُ وَحَتَّى أَنَّ الْمَرْأَةَ لَتَمُرُّ ‏ ‏بِالْبَعْلِ ‏ ‏فَيَنْظُرُ إِلَيْهَا فَيَقُولُ لَقَدْ كَانَ لِهَذِهِ مَرَّةً رَجُلٌ ‏ ‏ذَكَرَهُ ‏ ‏حَمَّادٌ ‏ ‏مَرَّةً هَكَذَا وَقَدْ ذَكَرَهُ عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَشُكُّ فِيهِ وَقَدْ قَالَ أَيْضًا عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْسِبُ ‏","","",""],[13537,13537,"","আমরা টাইমস নিয়ে কথা বলেছি যখন তারা তাদের স্বপ্নের মধ্যে এসেছিল। ঈশ্বর তাদের আমাদের সাথে যেতে হবে, মানুষ আমাদের এই বছর শিক্ষা দিতে হবে এবং আমাদের জীবনের সেরাটা গ্রহণের জন্য আমাদের কাছে অনুরোধ করতে হবে। এই মা যেন চায়","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ أَهْلَ ‏ ‏الْيَمَنِ ‏ ‏لَمَّا قَدِمُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا ابْعَثْ مَعَنَا رَجُلًا يُعَلِّمُنَا السُّنَّةَ وَالْإِسْلَامَ قَالَ فَأَخَذَ بِيَدِ ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏وَقَالَ ‏ ‏هَذَا أَمِينُ هَذِهِ الْأُمَّةِ ‏","","",""],[13538,13538,"","আমরা একজন স্বপ্নের মায়ের কথা বলেছিলাম যে আমাদের স্বপ্নের কথা বলেছিল, তোমার মায়ের সাথে, একজন রাজার নাম হল শপথ করে বলতে যে আমার বাবার কখনো নেই মা, আমাদের একজন বড় লোক আছে তার সাথে কথা বলার জন্য... ...সে বলে সে কখনো ফোন করে না। আর আমি বলছি, ঈশ্বর তোমাকে জিতলে আমরা যারা তোমাকে জিতেছি, ঈশ্বরের ইচ্ছাতেই আমি তাদের খুন করি। আর আমি তোমাকে খুন করি। আর আমি যদি চাই, তুমি আমার কথা বলো, তুমি জানো, তুমি জানো, তুমি কি করো? হয়তো আমাদের ভালো হওয়া উচিত ছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏كَانَتْ مَعَ ‏ ‏أَبِي طَلْحَةَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَإِذَا مَعَ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏خِنْجَرٌ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏مَا هَذَا مَعَكِ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏اتَّخَذْتُهُ إِنْ دَنَا مِنِّي أَحَدٌ مِنْ الْكُفَّارِ ‏ ‏أَبْعَجُ ‏ ‏بِهِ بَطْنَهُ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَا نَبِيَّ اللَّهِ أَلَا تَسْمَعُ مَا تَقُولُ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏تَقُولُ كَذَا وَكَذَا فَقَالَتْ يَا رَسُولَ اللَّهِ أَقُتِلَ مَنْ بَعْدَنَا مِنْ ‏ ‏الطُّلَقَاءِ ‏ ‏انْهَزَمُوا بِكَ يَا رَسُولَ اللَّهِ فَقَالَ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ كَفَانَا وَأَحْسَنَ ‏","","",""],[13539,13539,"","আমি আমার ল্যাডারকে দিয়ে তাকে প্রার্থনা করতে হবে আর সুমৃগীকে সূর্য ভ্রমণ করতে হবে বলে শপথ করে বলছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُعْطِيَ ‏ ‏يُوسُفُ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏شَطْرَ ‏ ‏الْحُسْنِ ‏","","",""],[13540,13540,"","আমরা যে - বাপ্তিস্মের কথা বলেছিলাম, তা ঈশ্বরের কাছে পাওয়া যাবে বলে আমরা কথা বলতাম । গর্ভের কথা না বলা পর্যন্ত ঈশ্বরের কাছে প্রার্থনা করা না হলে...","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَثَابِتٌ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏كَانُوا ‏ ‏يَسْتَفْتِحُونَ الْقِرَاءَةَ بْ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏إِلَّا أَنَّ ‏ ‏حُمَيْدًا ‏ ‏لَمْ يَذْكُرْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13541,13541,"","আমি দেখলাম যে, আমি কিভাবে এক চতুর্থাংশব্যাকের কাছাকাছি ছিলাম, যে আমাদেরকে ভুল করে দিয়েছে। একজন উত্তম বালককে রসিকতা করার জন্য আদেশ দেওয়া হয়েছিল, যিনি পতাকা উত্তোলন করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ كَأَنِّي فِي دَارِ ‏ ‏عُقْبَةَ بْنِ رَافِعٍ ‏ ‏فَأُتِينَا بِرُطَبٍ مِنْ رُطَبِ ‏ ‏ابْنِ طَابٍ ‏ ‏فَأَوَّلْتُ ‏ ‏أَنَّ الرِّفْعَةَ لَنَا فِي الدُّنْيَا ‏ ‏وَالْعَاقِبَةَ ‏ ‏فِي الْآخِرَةِ وَأَنَّ دِينَنَا قَدْ طَابَ ‏","","",""],[13542,13542,"","আমরা ঈশ্বরের দোহাই দিয়ে বলছি যারা ভুলে গেছে তাদেরকে খুঁজে বের করার জন্য যে ঈশ্বর তাকে জিজ্ঞেস করেছেন, ঈশ্বর আমি তোমাকে আমার হাত থেকে দেখতে পাচ্ছি যখন আমরা আমার সাথে কথা বলেছি। সে বলেছে তারা গুলি করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اسْتَوُوا فَوَاللَّهِ إِنِّي لَأَرَاكُمْ مِنْ خَلْفِي كَمَا أَرَاكُمْ مِنْ بَيْنِ يَدَيَّ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏بِمِثْلِهِ غَيْرَ أَنَّهُ قَالَ اسْتَوُوا وَتَرَاصُّوا ‏","","",""],[13543,13543,"","আমি তোমার টাকা ভুলে যাওয়ার কথা বলেছিলাম, ঈশ্বরের উত্তর ছিল, আমি হয়তো ঈশ্বরকে ভয় করতাম, কারণ আমি শুধু ভয় পেতাম যে, আমি এমন এক সময় ঈশ্বরকে আঘাত করেছি, এবং তখন আমি সেই সময়েরই ছিলাম যখন আমি ছিলাম। খুন, এক রাতের খাবার আমার কাছে নেই... ...আর সেটা ছাড়া আমি পড়তে চাই.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَقَدْ أُخِفْتُ فِي اللَّهِ عَزَّ وَجَلَّ وَمَا يَخَافُ أَحَدٌ وَلَقَدْ أُوذِيتُ فِي اللَّهِ وَمَا ‏ ‏يُؤْذَى أَحَدٌ وَلَقَدْ أَتَتْ عَلَيَّ ثَلَاثُونَ مِنْ بَيْنِ يَوْمٍ وَلَيْلَةٍ وَمَا لِي وَلَا ‏ ‏لِبِلَالٍ ‏ ‏طَعَامٌ يَأْكُلُهُ ‏ ‏ذُو كَبِدٍ ‏ ‏إِلَّا شَيْءٌ ‏ ‏يُوَارِيهِ ‏ ‏إِبِطُ ‏ ‏بِلَالٍ ‏","","",""],[13544,13544,"","আমরা একটা বাপ্তিস্মের বিষয়ে কথা বলেছিলাম, যেটা আমাদের মুখ বন্ধ রাখতে বলা হয়েছিল । আমি যখন গ্রেফতার হই, তখন বিজয় হয়, যতক্ষণ না পর্যন্ত তাকে হত্যা করা হয়, লর্ডের কাছে প্রার্থনা করে এবং আমাদের আত্মার প্রতি তার সমবেদনা স্বীকার করে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏وَعَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ الْمُشْرِكِينَ لَمَّا ‏ ‏رَهِقُوا ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي سَبْعَةٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَرَجُلَيْنِ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏قَالَ ‏ ‏مَنْ يَرُدُّهُمْ عَنَّا وَهُوَ رَفِيقِي فِي الْجَنَّةِ فَجَاءَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَاتَلَ حَتَّى قُتِلَ فَلَمَّا ‏ ‏أَرْهَقُوهُ ‏ ‏أَيْضًا قَالَ مَنْ يَرُدُّهُمْ عَنِّي وَهُوَ رَفِيقِي فِي الْجَنَّةِ حَتَّى قُتِلَ السَّبْعَةُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِصَاحِبِهِ مَا أَنْصَفْنَا إِخْوَانَنَا ‏","","",""],[13545,13545,"","ঈশ্বরের প্রতিজ্ঞার জন্য শহরকে প্রশংসা করা এবং লোকেদের কাছে সমর্পণ করা, ঈশ্বর তাদের কাছে প্রতিজ্ঞা করেছেন । ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং নিজেকে সমর্পণ করেছেন যে, ঈশ্বর হলেন আমার সবচেয়ে দরিদ্র আত্মার সর্বোত্তম প্রত্যাশা । সারাজীবনের জন্য টাকা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏وَثَابِتٌ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏غَلَا السِّعْرُ ‏ ‏بِالْمَدِينَةِ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّاسُ يَا رَسُولَ اللَّهِ غَلَا السِّعْرُ سَعِّرْ لَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ هُوَ الْمُسَعِّرُ الْقَابِضُ الْبَاسِطُ الرَّزَّاقُ إِنِّي لَأَرْجُو أَنْ أَلْقَى اللَّهَ عَزَّ وَجَلَّ وَلَيْسَ أَحَدٌ مِنْكُمْ يَطْلُبُنِي بِمَظْلَمَةٍ فِي دَمٍ وَلَا مَالٍ ‏","","",""],[13546,13546,"","ঈশ্বর তাকে জানেন এবং আমি একজন ব্যক্তি ও ভাববাদী তার জ্ঞান ও আত্মসমর্পণ করি ( গীতসংহিতা ৩৭: ১১) ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর ব্যক্তিকে সমর্পণ করবেন এবং তাঁর ইচ্ছা পালন করবেন । তোমাকে সরানোর জন্য তোমার মুক্তির কোন প্রয়োজন নেই, ঈশ্বরের কাছে আছে আর সে বলবে আমি চামড়া, আমার গায়ে আলখাল্লা আছে আর সে আমাকে বিরক্ত করছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا طَلْحَةَ ‏ ‏كَانَ يَرْمِي بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَلْفَهُ ‏ ‏يَتَتَرَّسُ ‏ ‏بِهِ وَكَانَ رَامِيًا وَكَانَ ‏ ‏إِذَا رَمَى رَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَخْصَهُ ‏ ‏يَنْظُرُ أَيْنَ يَقَعُ سَهْمُهُ وَيَرْفَعُ ‏ ‏أَبُو طَلْحَةَ ‏ ‏صَدْرَهُ وَيَقُولُ هَكَذَا بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ ‏ ‏لَا يُصِيبُكَ سَهْمٌ ‏ ‏نَحْرِي ‏ ‏دُونَ ‏ ‏نَحْرِكَ ‏ ‏وَكَانَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَسُوقُ نَفْسَهُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيَقُولُ إِنِّي ‏ ‏جَلْدٌ ‏ ‏يَا رَسُولَ اللَّهِ فَوَجِّهْنِي فِي حَوَائِجِكَ وَمُرْنِي بِمَا شِئْتَ ‏","","",""],[13547,13547,"","আমরা একজন বয়ফ্রেন্ডের সাথে কথা বলেছি, যার কাছে ঈশ্বরের সবচেয়ে ভাল মানুষ ছিল। সে এটা দেখেছে বাবার কামনার পোশাক তার জীবনের মোড়কে ঘিরে তার বাবার স্বপ্নকে সরিয়ে নিয়ে... তার মা ছিলেন একজন স্বপ্নবী আর তিনি একজন স্বপ্নবী ছিলেন । ভবিষ্যদ্বাণী, তার কাছে প্রার্থনা করো আর সে বলবে তুমি কি করো, অথবা সে যা বলে, আমি তা করব।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا أَرَادَ أَنْ يَحْلِقَ رَأْسَهُ ‏ ‏بِمِنًى ‏ ‏أَخَذَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏شِقَّ ‏ ‏رَأْسِهِ فَحَلَقَ ‏ ‏الْحَجَّامُ ‏ ‏فَجَاءَ بِهِ إِلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏وَكَانَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏تَجْعَلُهُ فِي ‏ ‏مِسْكِهَا ‏ ‏وَكَانَ يَجِيءُ ‏ ‏فَيَقِيلُ ‏ ‏عِنْدَهَا عَلَى ‏ ‏نِطْعٍ ‏ ‏وَكَانَ ‏ ‏مِعْرَاقًا ‏ ‏فَجَاءَ ذَاتَ يَوْمٍ فَجَعَلَتْ ‏ ‏تَسْلُتُ ‏ ‏الْعَرَقَ وَتَجْعَلُهُ فِي ‏ ‏قَارُورَةٍ ‏ ‏لَهَا فَاسْتَيْقَظَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا تَجْعَلِينَ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَتْ يَا نَبِيَّ اللَّهِ ‏ ‏عَرَقُكَ أُرِيدُ أَنْ ‏ ‏أَدُوفَ ‏ ‏بِهِ طِيبِي ‏","","",""],[13548,13548,"","আমরা তোমার টাকা ভুলে যেতে বলেছিলাম যখন আমরা সরিয়েছিলাম তুমি তোমার কণ্ঠ ভুলে যাবে না এই বলে যে সে তার আত্মা হারিয়ে গেছে। সে একজন প্রফেসর, বাবা, যে কখনোই তোমার সাথে যাবে না। তিনি তার সেবায় গিয়েছিলেন, উল্লেখ করেছিলেন যে, ভাববাদীর কথা, যিনি তা করতে পারতেন এবং বলেছিলেন তিনি বলেছিলেন যে তিনি বলেছিলেন যে তিনি বলেছিলেন যে তিনি বলতে চান । ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি বলেছিলেন যে, তিনি তার কাছ থেকে এসেছেন । অপরাধ.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ ‏} ‏قَالَ قَعَدَ ‏ ‏ثَابِتُ بْنُ قَيْسٍ ‏ ‏فِي بَيْتِهِ فَفَقَدَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لِسَعْدِ بْنِ مُعَاذٍ ‏ ‏يَا ‏ ‏أَبَا عَمْرٍو ‏ ‏مَا شَأْنُ ‏ ‏ثَابِتِ بْنِ قَيْسٍ ‏ ‏لَا يُرَى ‏ ‏أَاشْتَكَى ‏ ‏فَقَالَ مَا عَلِمْتُ لَهُ بِمَرَضٍ وَإِنَّهُ لَجَارِي فَدَخَلَ عَلَيْهِ ‏ ‏سَعْدٌ ‏ ‏فَذَكَرَ لَهُ قَوْلَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ قَدْ عَلِمْتَ أَنِّي كُنْتُ مِنْ أَشَدِّكُمْ رَفْعَ صَوْتٍ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ نَزَلَتْ هَذِهِ الْآيَةُ وَقَدْ هَلَكْتُ أَنَا مِنْ أَهْلِ النَّارِ فَذَكَرَ ذَلِكَ ‏ ‏سَعْدٌ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بَلْ هُوَ مِنْ أَهْلِ الْجَنَّةِ ‏","","",""],[13549,13549,"","আমরা অতীত থেকে আসা লোকদের কথা বলেছি, সে তাদের সাথে কাজ করেছে, আল্লাহ তার জন্য প্রার্থনা করেছে এবং তারা তার কাছে আত্মসমর্পণ করেছে এবং বলছে তারা তার বাসায় আত্মসমর্পণ করেছে এবং বলছে তারা গর্ভ থেকে পান করেছে। আর আত্মসমর্পণ করবে ঈশ্বরের প্রভু হতে, আমি তাদের মাথা থেকে বের করে দেবো... ...আর আমি তাদের পেরেক দিয়ে ফেলে দেবো... ...যেন তারা মুক্ত হবে, আমি এটা নিয়ে বেশি চিন্তা করি। তারা মারা যাওয়ার আগে, হয়তো সে বলেছে হামাদ তাকে ধ্বংস করে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَاسًا مِنْ ‏ ‏عُرَيْنَةَ ‏ ‏قَدِمُوا ‏ ‏الْمَدِينَةَ ‏ ‏فَاجْتَوَوْهَا ‏ ‏فَبَعَثَ بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي إِبِلِ ‏ ‏الصَّدَقَةِ ‏ ‏وَقَالَ ‏ ‏اشْرَبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا فَقَتَلُوا ‏ ‏رَاعِيَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْتَاقُوا الْإِبِلَ وَارْتَدُّوا عَنْ الْإِسْلَامِ فَأُتِيَ بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَطَعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ مِنْ ‏ ‏خِلَافٍ ‏ ‏وَسَمَرَ ‏ ‏أَعْيُنَهُمْ وَأَلْقَاهُمْ ‏ ‏بِالْحَرَّةِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏قَدْ كُنْتُ أَرَى أَحَدَهُمْ ‏ ‏يَكْدُمُ ‏ ‏الْأَرْضَ بِفِيهِ حَتَّى مَاتُوا ‏ ‏وَرُبَّمَا قَالَ ‏ ‏حَمَّادٌ ‏ ‏يَكْدُمُ ‏ ‏الْأَرْضَ بِفِيهِ حَتَّى مَاتُوا ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏وَهَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏بِنَحْوِ حَدِيثِ ‏ ‏حَمَّادٍ ‏","","",""],[13550,13550,"","আমরা বাবার কথা বলেছিলাম তার চেয়ে মহান ঈশ্বরকে খুঁজে পেতে. আমরা স্বাধীনতা নিয়ে গিয়েছিলাম এবং তারপর তারা দেখতে গিয়েছিল যে তারা দুজন লোক তাদের বিশ্বাস হারিয়ে ফেলেছে কিনা। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏كَانَ ‏ ‏رَدِيفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَخْتَلِفُ ‏ ‏إِلَى ‏ ‏الشَّامِ ‏ ‏وَكَانَ يُعْرَفُ وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُعْرَفُ فَكَانُوا يَقُولُونَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏مَا هَذَا الْغُلَامُ بَيْنَ يَدَيْكَ قَالَ هَذَا يَهْدِينِي السَّبِيلَ فَلَمَّا دَنَوْا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏نَزَلَا ‏ ‏الْحَرَّةَ ‏ ‏وَبَعَثَا إِلَى ‏ ‏الْأَنْصَارِ ‏ ‏فَجَاءُوا فَقَالُوا قُومَا آمِنَيْنِ مُطَاعَيْنِ قَالَ فَشَهِدْتُهُ يَوْمَ دَخَلَ ‏ ‏الْمَدِينَةَ ‏ ‏فَمَا رَأَيْتُ يَوْمًا قَطُّ كَانَ أَحْسَنَ وَلَا ‏ ‏أَضْوَأَ مِنْ يَوْمٍ دَخَلَ عَلَيْنَا فِيهِ وَشَهِدْتُهُ يَوْمَ مَاتَ فَمَا رَأَيْتُ يَوْمًا كَانَ أَقْبَحَ وَلَا أَظْلَمَ مِنْ يَوْمٍ مَاتَ فِيهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13551,13551,"","আমরা ঈশ্বরের দোহাই আপনাকে খুঁজে পেতে, তিন দিন, এমনকি তারা চলে গেছে, এবং তারপর তারা বলতে চায়, \"আমি নিশ্চিত নই\", গুড লেডি, হয়তো কি খুঁজে পেয়েছে। তুমি প্রতিজ্ঞা করেছিলে, তিনি তাকে চুপ করিয়ে দিলেন, আমি তিন ঘটনার পর তাদের ফোন করেছি এবং তিনি বললেন ঈশ্বর পিপাসার্ত আর তুমি বলবে তার হাতে আমরা নিঃশ্বাস নিতে তারা উত্তর দিতে পারে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرَكَ قَتْلَى ‏ ‏بَدْرٍ ‏ ‏ثَلَاثَةَ أَيَّامٍ حَتَّى ‏ ‏جَيَّفُوا ‏ ‏ثُمَّ أَتَاهُمْ فَقَامَ عَلَيْهِمْ فَقَالَ يَا ‏ ‏أُمَيَّةُ بْنَ خَلَفٍ ‏ ‏يَا ‏ ‏أَبَا جَهْلِ بْنَ هِشَامٍ ‏ ‏يَا ‏ ‏عُتْبَةُ بْنَ رَبِيعَةَ ‏ ‏يَا ‏ ‏شَيْبَةُ بْنَ رَبِيعَةَ ‏ ‏هَلْ وَجَدْتُمْ مَا وَعَدَكُمْ رَبُّكُمْ حَقًّا فَإِنِّي قَدْ وَجَدْتُ مَا وَعَدَنِي رَبِّي حَقًّا قَالَ فَسَمِعَ ‏ ‏عُمَرُ ‏ ‏صَوْتَهُ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَتُنَادِيهِمْ بَعْدَ ثَلَاثٍ وَهَلْ يَسْمَعُونَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّكَ لَا تُسْمِعُ الْمَوْتَى ‏} ‏فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ مَا أَنْتُمْ بِأَسْمَعَ مِنْهُمْ وَلَكِنَّهُمْ لَا يَسْتَطِيعُونَ أَنْ يُجِيبُوا ‏","","",""],[13552,13552,"","আমরা বাবা মারা যাওয়ার কথা বলেছিলাম, বাবাকে এমনকি তাকেও বলতে না যে সে বিছানায় যাবে। তারপর তাকে বলা হয়েছিল সে যেন তার থেকে আসতে পারে, সে কয়েক বছর আগে, সে তা করেনি। বাবা কখনোই তা করেননি বলে তিনি বলেছিলেন । তার শান্তি আদেশ করে এবং তার সর্বোচ্চ চেষ্টা করে সে মিথ্যা বলছে। সে ঈশ্বরের কাছে বলেছিল, সে এটা করেছে। তারপর সে তার খেলা শুরু করল এবং সে তার মুখের সামনে টেনে নেয়। ঈশ্বর সেই বিজয়ের প্রতি ভালোবাসা দেখিয়েছেন, যা আপনি ঈশ্বরের সামনে করেছিলেন, যখন সেটা অন্ধকারে ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا طَلْحَةَ ‏ ‏مَاتَ لَهُ ابْنٌ فَقَالَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏لَا تُخْبِرُوا ‏ ‏أَبَا طَلْحَةَ ‏ ‏حَتَّى أَكُونَ أَنَا الَّذِي أُخْبِرُهُ ‏ ‏فَسَجَّتْ ‏ ‏عَلَيْهِ فَلَمَّا جَاءَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏وَضَعَتْ بَيْنَ يَدَيْهِ طَعَامًا فَأَكَلَ ثُمَّ تَطَيَّبَتْ لَهُ فَأَصَابَ مِنْهَا ‏ ‏فَعَلِقَتْ ‏ ‏بِغُلَامٍ فَقَالَتْ يَا ‏ ‏أَبَا طَلْحَةَ ‏ ‏إِنَّ آلَ فُلَانٍ اسْتَعَارُوا مِنْ آلِ فُلَانٍ ‏ ‏عَارِيَةً ‏ ‏فَبَعَثُوا إِلَيْهِمْ ابْعَثُوا إِلَيْنَا بِعَارِيَتِنَا فَأَبَوْا أَنْ يَرُدُّوهَا فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏لَيْسَ لَهُمْ ذَلِكَ إِنَّ ‏ ‏الْعَارِيَةَ ‏ ‏مُؤَدَّاةٌ إِلَى أَهْلِهَا قَالَتْ فَإِنَّ ابْنَكَ كَانَ ‏ ‏عَارِيَةً ‏ ‏مِنْ اللَّهِ عَزَّ وَجَلَّ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ قَبَضَهُ ‏ ‏فَاسْتَرْجَعَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَأُخْبِرَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَلِكَ فَقَالَ ‏ ‏بَارَكَ اللَّهُ لَهُمَا فِي لَيْلَتِهِمَا قَالَ ‏ ‏فَعَلِقَتْ ‏ ‏بِغُلَامٍ فَوَلَدَتْ فَأَرْسَلَتْ بِهِ مَعِي ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَمَلْتُ تَمْرًا فَأَتَيْتُ بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ عَبَاءَةٌ وَهُوَ ‏ ‏يَهْنَأُ ‏ ‏بَعِيرًا لَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ مَعَكَ تَمْرٌ قَالَ قُلْتُ نَعَمْ فَأَخَذَ التَّمَرَاتِ فَأَلْقَاهُنَّ فِي ‏ ‏فِيهِ ‏ ‏فَلَاكَهُنَّ ‏ ‏ثُمَّ جَمَعَ لُعَابَهُ ثُمَّ ‏ ‏فَغَرَ ‏ ‏فَاهُ ‏ ‏فَأَوْجَرَهُ ‏ ‏إِيَّاهُ فَجَعَلَ الصَّبِيُّ ‏ ‏يَتَلَمَّظُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُبُّ ‏ ‏الْأَنْصَارَ ‏ ‏التَّمْرَ ‏ ‏فَحَنَّكَهُ ‏ ‏وَسَمَّاهُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَمَا كَانَ فِي ‏ ‏الْأَنْصَارِ ‏ ‏شَابٌّ أَفْضَلَ مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامُ بْنُ مِسْكِينٍ ‏ ‏فَذَكَرَهُ ‏","","",""],[13553,13553,"","আমরা ঈশ্বর তার শান্তি প্রেরণ করার কথা বলেছিলাম এবং অনুমান করেছিলাম যে, তাকে ভালোবাসে। সে যখন ফিরে এসেছে, তখন সে হার মেনে নিয়েছে। দ্রুত তাকে ছেড়ে দেওয়া হয়েছে। তাকে উদ্ধার করা হয়নি, তুমি এখনো পর্যন্ত কর নি, এই জেল ঠিক আছে আর শেষটাও ঠিক আছে...","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى رَجُلٍ مِنْ أَصْحَابِهِ ‏ ‏يَعُودُهُ ‏ ‏وَقَدْ صَارَ كَالْفَرْخِ فَقَالَ لَهُ هَلْ سَأَلْتَ اللَّهَ عَزَّ وَجَلَّ قَالَ قُلْتُ اللَّهُمَّ مَا كُنْتَ مُعَاقِبِي بِهِ فِي الْآخِرَةِ فَعَجِّلْهُ فِي الدُّنْيَا فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا طَاقَةَ لَكَ بِعَذَابِ اللَّهِ هَلَّا قُلْتَ ‏ ‏اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ ‏","","",""],[13554,13554,"","আমরা যারা আমাকে ভালোবাসার চেষ্টা করছিল তারা বলছিল তারা আমাদের সাথে বিশ্বাসঘাতকতার প্রশংসা করবে... ...আমরা বাকিদের জন্য যারা আমাদের জন্য চেষ্টা করে তাদের রক্ষা করা হবে. যে ভালোটা তাকে জোর করে ক্ষমা করে দিতে পারে, সে একজন কবি আর বিভ্রান্তকারী দাসকে উদ্ধার করবে, যে তাকে খেয়ে ফেলেছে আর বলছে যে ভবিষ্যদ্বাণীটা সফল হয়েছে। এক।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانُوا يَقُولُونَ وَهُمْ يَحْفِرُونَ ‏ ‏الْخَنْدَقَ ‏ ‏نَحْنُ الَّذِينَ ‏ ‏بَايَعُوا ‏ ‏مُحَمَّدًا ‏ ‏عَلَى الْإِسْلَامِ مَا بَقِينَا أَبَدًا ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنَّ الْخَيْرَ خَيْرُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِخُبْزِ شَعِيرٍ ‏ ‏وَإِهَالَةٍ ‏ ‏سَنِخَةٍ ‏ ‏فَأَكَلُوا مِنْهَا وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا الْخَيْرُ خَيْرُ ‏ ‏الْآخِرَهْ ‏","","",""],[13555,13555,"","আমরা ইশ্বরকে আমাদের বলতে চেয়েছিলাম যে আমি দুঃখিত, সে সিঁড়ি দিয়ে যাচ্ছে আর মেঘের সাথে খেলছে তার টুকরো থেকে শয়তান তাকে মুছে ফেলেছে জোম্বি পানিতে ফিরে এসে তার জায়গায় ফিরে এসে তার জায়গায় ফিরে এসে, মানে তার পিঠে বলা আছে যে জেব্রা মারা গেছে, আর সে স্বাক্ষর করেছে ঘুমের মধ্যে, হয়তো সে বলেছে হামাদকে তার সর্বোচ্চ মঙ্গলের জন্য পাঠাতে হবে, আর সে তাকে হাত দিতে পারত।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَهُوَ يَلْعَبُ مَعَ الْغِلْمَانِ فَأَخَذَهُ ‏ ‏فَصَرَعَهُ ‏ ‏فَشَقَّ عَنْ قَلْبِهِ فَاسْتَخْرَجَ مِنْهُ ‏ ‏عَلَقَةً ‏ ‏فَقَالَ هَذَا حَظُّ الشَّيْطَانِ مِنْكَ ثُمَّ غَسَلَهُ فِي ‏ ‏طَسْتٍ ‏ ‏مِنْ ذَهَبٍ بِمَاءِ ‏ ‏زَمْزَمَ ‏ ‏ثُمَّ ‏ ‏لَأَمَهُ ‏ ‏وَأَعَادَهُ فِي مَكَانِهِ وَجَاءَ الْغِلْمَانُ يَسْعَوْنَ إِلَى أُمِّهِ ‏ ‏يَعْنِي ‏ ‏ظِئْرِهِ ‏ ‏فَقَالُوا إِنَّ ‏ ‏مُحَمَّدًا ‏ ‏قَدْ قُتِلَ فَاسْتَقْبَلُوهُ وَهُوَ ‏ ‏مُنْتَقِعُ ‏ ‏اللَّوْنِ قَالَ لِي ‏ ‏أَنَسٌ ‏ ‏فَكُنْتُ أَرَى أَثَرَ الْمِخْيَطِ فِي صَدْرِهِ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏حَمَّادٌ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاهُ آتٍ ‏","","",""],[13556,13556,"","আমরা ঈশ্বরের দোহাই নিয়ে তিন বছর ধরে কথা বলেছি, ইমান স্যুটটা পেয়েছি যে আল্লাহ্ জিতেছে আর পছন্দ করেছেন। আর তাকেও যেন অভিশাপ দেয়া হয়। আমি তাকে পছন্দ করি, আমি যেন তাকে ধরে রাখি। আমাকে হুমকি বা জোর করে বলার জন্য.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلَاوَةَ الْإِيمَانِ مَنْ كَانَ اللَّهُ عَزَّ وَجَلَّ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَالرَّجُلُ يُحِبُّ الرَّجُلَ لَا يُحِبُّهُ إِلَّا لِلَّهِ وَالرَّجُلُ أَنْ يُقْذَفَ فِي النَّارِ أَحَبُّ إِلَيْهِ مِنْ أَنْ يَرْجِعَ يَهُودِيًّا أَوْ نَصْرَانِيًّا ‏","","",""],[13557,13557,"","আমরা মসজিদ নিয়ে কথা বলেছি যেখানে মানুষ বলে যে এটা ঈশ্বরের ইচ্ছা। আমাদের ছোট ভাই ছিল তার নিজের মুখের সাথে খেলা করার মত পরিবর্তন। সে তার নিজের অধিকার ছেড়ে দিয়েছে, বলতে যে আমার বাবার সাথে তার কোন সম্পর্ক নেই, কিন্তু সে বলেছে সে ঈর্ষান্বিত। সে বলেছে বাবা ভালো কিছু করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ عَلَيْنَا وَكَانَ لِي أَخٌ صَغِيرٌ وَكَانَ لَهُ ‏ ‏نُغَيْرٌ ‏ ‏يَلْعَبُ بِهِ فَمَاتَ ‏ ‏نُغَرُهُ ‏ ‏الَّذِي كَانَ يَلْعَبُ بِهِ فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَرَآهُ حَزِينًا فَقَالَ لَهُ مَا شَأْنُ ‏ ‏أَبِي عُمَيْرٍ ‏ ‏حَزِينًا فَقَالُوا مَاتَ ‏ ‏نُغَرُهُ ‏ ‏الَّذِي كَانَ يَلْعَبُ بِهِ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏","","",""],[13558,13558,"","আমরা ঈশ্বরের কাছে পাঠানো কথা বলেছিলাম, তিনি বলেছিলেন, তিনি এটা করতে বলেছেন। আমি তাকে জিজ্ঞাসা করছি, কিভাবে তিনি তাঁদের খুঁজে বের করতে পারেন। তোমার জন্য কোন কিছুর মাধ্যমে যেতে হবে না, অথবা অত্যাচার করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَهُوَ ‏ ‏يَسْلِتُ ‏ ‏الدِّمَاءَ عَنْ وَجْهِهِ كَيْفَ يُفْلِحُ قَوْمٌ ‏ ‏شَجُّوا ‏ ‏وَجْهَ نَبِيِّهِمْ وَكَسَرُوا ‏ ‏رَبَاعِيَتَهُ ‏ ‏وَهُوَ يَدْعُوهُمْ إِلَى اللَّهِ عَزَّ وَجَلَّ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏لَيْسَ لَكَ مِنْ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ ‏}","","",""],[13559,13559,"","আমরা একজন লোক কথা বলেছি যে ভগবানের কাছে বলতে চাই, তাকে ঘন্টার পর ঘন্টা দেয়া হয়েছে আর প্রার্থনা ঠিক আছে যখন তাকে জিজ্ঞেস করা হয়েছে যে তিনি কি না যাচ্ছেন আমি কথা দিচ্ছি যে আমি অনেক কাজ করতে ভালোবাসি। আপনি তার সাথে আছেন, যিনি প্রশ্ন করার পর আমাকে ডেলেক্ট দেয়া হবে। আমরা ঈশ্বর এবং তিনি অনেক কিছু করতে চাই। আমি আপনাকে অনেক কাজ করতে চাই। আপনি কি জানেন না? আপনি কি, আপনি জানেন, আপনি কি বলেন, আপনি জানেন না? আপনি কি? আপনি কি বলেন, আপনি জানেন, আপনি কি আছে? আপনি কি? আপনি কি আছে? আপনি জানেন, আপনি কি? আপনি যদি আপনি জানেন না আপনি জানেন, আপনি জানেন, আপনি আপনার জন্য একটি ছোট দল পাবেন। আপনি আপনার সন্তান। আপনি কি করতে চান? আপনি আপনার সন্তান পাবেন? আপনি কি? আপনি কি? আপনি আপনার সন্তান আপনি কি? আপনি কি আছে? আপনি কি? আপনি কি? আপনি জানেন না? আপনি যদি আপনি আপনার সন্তান আপনি জানেন, আপনি আপনার সন্তান পাবেন? আপনি কি? আপনি যদি আপনি আপনার সন্তান না? আপনি একটি ছোট ছোটদের জন্য একটি পরিবার পাবেন? আপনার জন্য একটি পরিবার আছে। আপনি কি? আপনার জন্য একটি পরিবার আছে? আপনার জন্য ধন্যবাদ। আপনি কি? আপনি কি? আপনার জন্য ধন্যবাদ। আপনি কি? আপনি কি? আপনি একটি ধন্যবাদ, এবং আপনার জন্য ধন্যবাদ। আপনি কি? আপনি আপনার জন্য ধন্যবাদ। আপনি কি? আপনি কি? আপনি কি? এবং আপনার জন্য ধন্যবাদ এবং আপনার জন্য ধন্যবাদ এবং আপনি কি? আপনি কি? এটা.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قِيَامِ السَّاعَةِ وَأُقِيمَتْ الصَّلَاةُ فَلَمَّا قَضَى صَلَاتَهُ قَالَ أَيْنَ السَّائِلُ عَنْ السَّاعَةِ قَالَ الرَّجُلُ أَنَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏مَا أَعْدَدْتَ لَهَا فَإِنَّهَا قَائِمَةٌ قَالَ مَا أَعْدَدْتُ لَهَا كَثِيرَ عَمَلٍ غَيْرَ أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏ ‏قَالَ ‏ ‏فَمَا فَرِحَ الْمُسْلِمُونَ بِشَيْءٍ بَعْدَ الْإِسْلَامِ مَا فَرِحُوا بِهَذَا الْحَدِيثِ قَالَ فَكَانَ ‏ ‏أَنَسٌ ‏ ‏يَقُولُ فَنَحْنُ نُحِبُّ اللَّهَ وَرَسُولَهُ ‏","","",""],[13560,13560,"","আমরা বাবার মৃত্যুর কথা বলেছিলাম, তাই সে আমাদের বলেছে আমার ছেলেকে মুছে ফেলতে। ঈশ্বর তাকে আগামী কয়েক বছরে তার মায়ের সাথে ভালোবাসায় তার ঘোড়াকে বদলে দিতে বলেছেন। আমি সেবা করছি। আমি নিশ্চিত যে তারা ঈশ্বরের কাছে প্রার্থনা করবে অথবা আমি এই কথা বলতে পারব। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তাকে সাহায্য করেছেন। ভাল, তারা তাদের সাথে লড়াই করতে সক্ষম হয়েছে, তার উত্তর দিয়ে আমরা বলেছিলাম, তারা হয়ত এটা করতে পেরে সন্তুষ্ট। হয়ত তারা বলেছে যে হয়ত তারা পড়তে পারে... ...তারপর আমরা তাদের ঈশ্বরের কাছে যাওয়ার পর ব্যবহার করব আর তোমাকে একটা সুযোগ দেব. ঈশ্বর প্রার্থনা করেছিলেন, যেন তিনি তাকে অথবা তার সাধুকে এই পরিদর্শনকারীদের কাছে পাঠান ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ خَالَهُ ‏ ‏حَرَامًا ‏ ‏أَخَا ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏فِي سَبْعِينَ إِلَى ‏ ‏بَنِي عَامِرٍ ‏ ‏فَلَمَّا قَدِمُوا قَالَ لَهُمْ خَالِي أَتَقَدَّمُكُمْ فَإِنْ أَمَّنُونِي حَتَّى أُبَلِّغَهُمْ عَنْ رَسُولِ اللَّهِ وَإِلَّا كُنْتُمْ مِنِّي قَرِيبًا قَالَ فَتَقَدَّمَ فَأَمَّنُوهُ فَبَيْنَمَا هُوَ يُحَدِّثُهُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ ‏ ‏أَوْمَئُوا ‏ ‏إِلَى رَجُلٍ فَطَعَنَهُ فَأَنْفَذَهُ فَقَالَ اللَّهُ أَكْبَرُ فُزْتُ وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏ثُمَّ مَالُوا عَلَى بَقِيَّةِ أَصْحَابِهِ فَقَتَلُوهُمْ إِلَّا رَجُلًا أَعْرَجَ مِنْهُمْ كَانَ قَدْ صَعِدَ الْجَبَلَ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏فَأُرَاهُ قَدْ ذَكَرَ مَعَ الْأَعْرَجِ آخَرَ مَعَهُ عَلَى الْجَبَلِ قَالَ وَحَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ أَنَّهُمْ قَدْ لَقُوا رَبَّهُمْ فَرَضِيَ عَنْهُمْ وَأَرْضَاهُمْ قَالَ ‏ ‏أَنَسٌ ‏ ‏كَانُوا يَقْرَءُونَ أَنْ بَلِّغُوا قَوْمَنَا أَنَّا قَدْ لَقِينَا رَبَّنَا فَرَضِيَ عَنَّا وَأَرْضَانَا قَالَ ثُمَّ ‏ ‏نُسِخَ ‏ ‏بَعْدَ ذَلِكَ فَدَعَا عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثِينَ صَبَاحًا عَلَى ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَبَنِي لِحْيَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏الَّذِينَ عَصَوْا اللَّهَ وَرَسُولَهُ ‏ ‏أَوْ عَصَوْا الرَّحْمَنَ ‏","","",""],[13561,13561,"","আমরা আমাদের কথোপকথনের কথা বলেছিলাম, কিন্তু আমাদের ছেলে ছেলে ছেলে, সে বলবে সে বিছানায় ছিল আর তার ঋণের মূল্য পরিশোধ করতো।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏التَّفْلُ فِي الْمَسْجِدِ خَطِيئَةٌ وَكَفَّارَتُهُ دَفْنُهَا ‏","","",""],[13562,13562,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং বলেছিলেন যে, তিনি তার আকাঙ্ক্ষার জন্য আকুল আকাঙ্ক্ষী । চুপ করো।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏كَيْفَ كَانَتْ قِرَاءَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ ‏ ‏يَمُدُّ صَوْتَهُ مَدًّا ‏","","",""],[13563,13563,"","আমরা কথা বলেছি এবং আমরা যারা ঈশ্বরের কথা বলছিল তাদের কথা বলছি, তিনি কখনো বড়দের উদ্ধার করতে পারতেন না এবং তারপর তারা প্রভুর মহিমার পরে পড়তে পারতেন। প্রার্থনা করে বললেন, আমরা তাদের কথা বলি, যারা ঈশ্বরের কাছে ঋণী তাদের কথা বলি। তারা কখনোই বড়দের কাছে ফিরে যেতে পারবে না। তারা কখনোই আমাদের কাছে এটা একটা বিষয় ছিল না। আমরা যদি তাদের কাছে এটা বলতে পারি, তাহলে আমরা কি করতে পারি, তারা আমাদের কাছে এটা একটা বড় বিষয় ছিল। আমরা যদি তাদের কাছে এটা একটা প্রশ্ন করি, তাহলে আমরা তাদের কাছে এটা একটা প্রশ্ন করি। কিন্তু আমরা কি তাদের কাছে এটা একটা বিষয় নিয়ে। আমরা কি করতে পারি? কিন্তু আমরা কি করতে পারি? আমরা কি করতে পারি? আমরা জানি না? আমরা জানি না যে, আমরা কি করি, আমরা তাদের কাছে এটা একটা বিষয় নিয়ে কথা বলেছি। আমরা যদি কিছু না, তাহলে আমরা শুধু একটা প্রশ্ন করি, আমাকে মাফ করে দাও... ...প্রতারণার পর দোয়া করতে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وحَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا ‏ ‏يَسْتَفْتِحُونَ الْقِرَاءَةَ بَعْدَ التَّكْبِيرِ بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏فِي الصَّلَاةِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏يَعْنِي فِي الصَّلَاةِ بَعْدَ التَّكْبِيرِ ‏","","",""],[13564,13564,"","আমরা ঈশ্বরকে তাঁর নিজের বংশধরের কাছে পাঠানো কথা বলেছি। তিনি বলেছিলেন, হয়তো তিনি তাদের সব কিছু শুনতে পারেন না। বিজ্ঞান অজানা এবং আত্মার ধনীতা দেখায়। সময়ের ভয়।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ ‏ ‏أَشْرَاطِ ‏ ‏السَّاعَةِ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏وَرُبَّمَا قَالَ لَا تَقُومُ السَّاعَةُ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏كِلَاهُمَا قَدْ سَمِعْتُ ‏ ‏حَتَّى ‏ ‏يُرْفَعَ ‏ ‏الْعِلْمُ وَيَظْهَرَ الْجَهْلُ وَتُشْرَبَ الْخَمْرُ وَيَظْهَرَ الزِّنَا وَيَقِلَّ الرِّجَالُ وَيَكْثُرَ النِّسَاءُ حَتَّى يَكُونَ لِخَمْسِينَ امْرَأَةً ‏ ‏الْقَيِّمُ ‏ ‏الْوَاحِدُ ‏","","",""],[13565,13565,"","আমি যখন শহরে যাই এবং ডাক্তারের সামনে যাই, তখন আমরা সেই দেওয়ালের মধ্য দিয়ে হেঁটে যাই, যা সে বলে । আমার হাত মারলো।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا أَسِيرُ فِي الْجَنَّةِ وَإِذَا أَنَا بِنَهَرٍ حَافَتَاهُ ‏ ‏قِبَابُ ‏ ‏الدُّرِّ ‏ ‏قَالَ قُلْتُ مَا هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا الْكَوْثَرُ الَّذِي أَعْطَاكَ رَبُّكَ عَزَّ وَجَلَّ قَالَ فَضَرَبْتُ بِيَدِي فَإِذَا طِينُهُ ‏ ‏مِسْكٌ ‏ ‏أَذْفَرُ ‏","","",""],[13566,13566,"","আমরা সেই ছেলেটির কথা বলেছিলাম যে তার হাত ধরে ছিল আর সে বলেছে যে তার নিজের রক্ত নিয়ে আমাদের কথা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْوِصَالِ ‏ ‏قَالَ قِيلَ لَهُ إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِي ‏","","",""],[13567,13567,"","আমরা কথা বলেছি তার জন্য আসা লোকদের পছন্দ করা আর সময় নিয়ে। মুখ আর মুখ, বেনের কাছ থেকে আমি এসেছি যতক্ষণ পর্যন্ত না পর্যন্ত সে সব বলে...","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ عِنْدَ ‏ ‏الزَّوَالِ ‏ ‏فَاحْتَاجَ أَصْحَابُهُ إِلَى الْوُضُوءِ قَالَ ‏ ‏فَجِيءَ ‏ ‏بِقَعْبٍ ‏ ‏فِيهِ مَاءٌ يَسِيرٌ فَوَضَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَفَّهُ فِيهِ فَجَعَلَ يَنْبُعُ مِنْ بَيْنِ أَصَابِعِهِ حَتَّى تَوَضَّأَ الْقَوْمُ كُلُّهُمْ ‏ ‏قُلْتُ كَمْ كُنْتُمْ ‏ ‏قَالَ ‏ ‏زُهَاءَ ‏ ‏ثَلَاثِ مِائَةٍ ‏","","",""],[13568,13568,"","এমনকি তিনি তার ভাইকে ভাল থেকে শ্বাস নিতে যেভাবে পছন্দ করেন, সেটাও পছন্দ করেন ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُؤْمِنُ عَبْدٌ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ مِنْ الْخَيْرِ ‏","","",""],[13569,13569,"","আমরা সেই ছেলের কথা বলেছিলাম যে তার হাত আর তার স্বপ্নের কথা বলে আমি আনন্দিত যে মোটা হয়ে ফিরে আসা কারো কাছে খুশি।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَهْلِ الْجَنَّةِ أَحَدٌ يَسُرُّهُ أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَلَهُ عَشَرَةُ أَمْثَالِهَا إِلَّا الشَّهِيدَ فَإِنَّهُ يَوَدُّ أَنَّهُ يَرْجِعُ إِلَى الدُّنْيَا فَاسْتُشْهِدَ عَشْرَ مَرَّاتٍ لِمَا رَأَى مِنْ الْفَضْلِ ‏","","",""],[13570,13570,"","আমরা ঈশ্বর সম্পর্কে আমাকে হুমকি দেওয়ার কথা বলেছিলাম সে তার সাহস বদলে ফেলবে বলে সে তার আত্মা জয় করবে। সে যখন আমাকে বলেছে সে বিষটা দিয়ে দিয়েছে সে আমার বিষটা হারালো তখন সে আত্মসমর্পণ করবে যখন সে আমাকে বিষটা নিয়ে গিয়েছিল তারা কখনও আমাকে পরিত্যাগ করেনি ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ يَهُودِيًّا مَرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابِهِ فَقَالَ ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ فَرَدَّ عَلَيْهِ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا قَالَ ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ فَأُخِذَ الْيَهُودِيُّ فَجِيءَ بِهِ فَاعْتَرَفَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُدُّوا عَلَيْهِمْ مَا قَالُوا ‏","","",""],[13571,13571,"","আমরা কথা বলেছিলাম যে লর্ড এটা করেছেন, তিনি একটি শহর থেকে দর্জি, তাই সে প্রতারণা এবং অপমানজনক। আমি যখন থেকে ভগবানের কাছে প্রার্থনা করতে দেখলাম, তখন থেকে আমি রেগে গেছি।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ دَعَاهُ خَيَّاطٌ مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏فَإِذَا ‏ ‏خُبْزُ شَعِيرٍ ‏ ‏وَإِهَالَةٌ ‏ ‏سَنِخَةٌ ‏ ‏قَالَ فَإِذَا فِيهَا قَرْعٌ قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ الْقَرْعُ قَالَ فَجَعَلْتُ أُقَرِّبُهُ قُدَّامَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏لَمْ أَزَلْ يُعْجِبُنِي الْقَرْعُ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ ‏","","",""],[13572,13572,"","আমরা মারা যাওয়ার কথা বলেছিলাম, তোমার টাকা ভুলে যেতে বলেছিলাম... ...যা আমি ন্যাংটা হয়ে দেখতে চাই... তারা বলেছে আমরা হয়ত শহর দখল করে ফেলেছি আর আমাদের মধ্যে কেউ কেউ হামলা করেছে. তারা আমার মাথায় প্রভাব ফেলবে আর তারা আমাকে মেরে ফেলবে. তারপর তাদের রঙগুলো হত্যা করা হয় এবং তারা ভবিষ্যদ্বাণীতে আটকে যায়, তারা শুধু তাদের হাত ধরে তাদের সরিয়ে নিয়ে যায় এবং তাদের উপর শাসন করার আহ্বান জানায়। এক বাঁধা।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏رَهْطًا ‏ ‏مِنْ ‏ ‏عُرَيْنَةَ ‏ ‏أَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا إِنَّا قَدْ ‏ ‏اجْتَوَيْنَا ‏ ‏الْمَدِينَةَ ‏ ‏فَعَظُمَتْ بُطُونُنَا وَانْتَهَشَتْ أَعْضَاؤُنَا ‏ ‏فَأَمَرَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَلْحَقُوا بِرَاعِي الْإِبِلِ فَيَشْرَبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا قَالَ فَلَحِقُوا بِرَاعِي الْإِبِلِ فَشَرِبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا حَتَّى صَلُحَتْ بُطُونُهُمْ وَأَلْوَانُهُمْ ثُمَّ قَتَلُوا ‏ ‏الرَّاعِي ‏ ‏وَسَاقُوا الْإِبِلَ فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَعَثَ فِي طَلَبِهِمْ فَجِيءَ بِهِمْ فَقَطَعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ ‏ ‏وَسَمَرَ ‏ ‏أَعْيُنَهُمْ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏إِنَّمَا كَانَ هَذَا قَبْلَ أَنْ تَنْزِلَ ‏ ‏الْحُدُودُ ‏","","",""],[13573,13573,"","আমরা যখন ঘরে ঘরে প্রচারে যেতাম, তখন আমরা আমাদের পরিবারের সঙ্গে দেখা করতে যেতাম । বেন এবং আমার উত্তরাধিকারী বলেন যে, আপনি যদি আমাকে দেখেন, তাহলে আমার আত্মা পরাজিত হবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُخْتَارُ بْنُ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةً فَأَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ ‏ ‏إِنِّي إِمَامُكُمْ فَلَا تَسْبِقُونِي بِالرُّكُوعِ وَلَا بِالسُّجُودِ وَلَا بِالْقِيَامِ فَإِنِّي أَرَاكُمْ مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي قَالَ ثُمَّ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ لَوْ رَأَيْتُمْ مَا رَأَيْتُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا قَالُوا يَا رَسُولَ اللَّهِ وَمَا رَأَيْتَ قَالَ رَأَيْتُ الْجَنَّةَ وَالنَّارَ ‏","","",""],[13574,13574,"","আমি আমার মা বলেছিলেন, আমি তাকে খুঁজে পাওয়ার চেষ্টা করার সময় মা তার বাবার সঙ্গে কথা না বলতে চেয়েছিলেন । যতক্ষণ না সে অভিভাবক হয়ে গেল, ততক্ষণ পর্যন্ত আমি তার জন্য কেঁদেছিলাম। আগামীকাল আমি তার ইচ্ছার সাথে না গিয়ে তাকে খেতে। সে আমার মাকে আমার মাকে দিয়ে নয়, আমার মাকেও নয়। যে ছেলে বলেছে সে তার হাতের সাথে ঘুমাচ্ছিল.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَاتَ ابْنٌ ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏مِنْ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏قَالَ فَقَالَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏لِأَهْلِهَا لَا تُحَدِّثُوا ‏ ‏أَبَا طَلْحَةَ ‏ ‏بِابْنِهِ حَتَّى أَكُونَ أَنَا أُحَدِّثُهُ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏بَهْزٍ ‏ ‏إِلَّا أَنَّهُ قَالَ ‏ ‏قَالَتْ أُمِّي يَا ‏ ‏أَنَسُ ‏ ‏لَا يُطْعَمْ شَيْئًا حَتَّى ‏ ‏تَغْدُوَ ‏ ‏بِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَبَاتَ يَبْكِي وَبِتُّ ‏ ‏مُجْتَنِحًا ‏ ‏عَلَيْهِ ‏ ‏أُكَالِئُهُ ‏ ‏حَتَّى أَصْبَحْتُ ‏ ‏فَغَدَوْتُ ‏ ‏بِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا مَعَهُ ‏ ‏مِيسَمٌ ‏ ‏فَلَمَّا رَأَى الصَّبِيَّ مَعِي قَالَ ‏ ‏لَعَلَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَلَدَتْ قَالَ قُلْتُ نَعَمْ فَوَضَعَ ‏ ‏الْمِيسَمَ ‏ ‏مِنْ يَدِهِ وَقَعَدَ ‏","","",""],[13575,13575,"","আমরা ঈশ্বর তার শান্তির জন্য পাঠানো সম্পর্কে কথা বলেছি, আমরা সব বলে দিয়েছি, আসবাবপত্রগুলো খেতে পারি এবং বলতে চাই যদি আমি একা এটা করতে চাই, আমরা সংবাদপত্রকে আদেশ দিয়েছি তুমি জানো না। তোমার মহিমা আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا أَكَلَ طَعَامًا لَعِقَ أَصَابِعَهُ الثَّلَاثَ وَقَالَ ‏ ‏إِذَا وَقَعَتْ لُقْمَةُ أَحَدِكُمْ ‏ ‏فَلْيُمِطْ ‏ ‏عَنْهَا الْأَذَى وَلْيَأْكُلْهَا وَلَا يَدَعْهَا لِلشَّيْطَانِ وَأَمَرَنَا أَنْ ‏ ‏نَسْلِتَ ‏ ‏الصَّحْفَةَ وَقَالَ إِنَّكُمْ لَا تَدْرُونَ فِي أَيِّ طَعَامِكُمْ الْبَرَكَةَ ‏","","",""],[13576,13576,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি আত্মসমর্পণ করব এবং সেই বনরক্ষী বাহিনীর কাছ থেকে অপসারণ করা হবে । সে তাদের ব্যাপারে একটা স্বপ্ন ছেড়ে দেবে আর বানরটা তোমার সাথে যা করবে, সেটাই করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ثَمَانِينَ رَجُلًا مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏هَبَطُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابِهِ مِنْ ‏ ‏جَبَلِ التَّنْعِيمِ ‏ ‏عِنْدَ صَلَاةِ الْفَجْرِ فَأَخَذَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِلْمًا فَعَفَا عَنْهُمْ وَنَزَلَ الْقُرْآنُ ‏ { ‏وَهُوَ الَّذِي ‏ ‏كَفَّ ‏ ‏أَيْدِيَهُمْ عَنْكُمْ وَأَيْدِيَكُمْ عَنْهُمْ بِبَطْنِ ‏ ‏مَكَّةَ ‏ ‏مِنْ بَعْدِ أَنْ ‏ ‏أَظْفَرَكُمْ ‏ ‏عَلَيْهِمْ ‏}","","",""],[13577,13577,"","ঈশ্বরের কাছে এটা আছে আর আমি একটা আংটি নিয়ে আলোচনা করব, যেটা আমি আমার জন্য নিয়ে এসেছি আর শ্বাস নিয়ে আলোচনা করেছি ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّخَذَ خَاتَمًا وَنَقَشَ فِيهِ نَقْشًا فَقَالَ إِنِّي اتَّخَذْتُ خَاتَمًا وَنَقَشْتُ فِيهِ نَقْشًا فَلَا يَنْقُشْ أَحَدٌ عَلَى نَقْشِهِ ‏","","",""],[13578,13578,"","আমরা মানুষের সাথে কথা বলেছি... ...আমার লর্ড প্রভুর কাছে প্রার্থনা করছিল ডাক্তার বললো সে এটা খায়।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ الْقَرْعَ ‏ ‏أَوْ قَالَ ‏ ‏الدُّبَّاءَ ‏ ‏قَالَ فَرَأَيْتُهُ يَوْمًا يَأْكُلُهُ فَجَعَلْتُ أَضَعُهُ بَيْنَ يَدَيْهِ ‏","","",""],[13579,13579,"","আমরা কিভাবে তোমাকে ঈশ্বর আশীর্বাদ করেছেন সে সম্পর্কে কথা বলেছি, ঈশ্বরের প্রার্থনা তাকে তাঁর কাছে নিয়ে যাবে এবং তাকে আপনার রাজার নামে গ্রহণ করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ بِخَمْسَةِ ‏ ‏مَكَاكِيكَ ‏ ‏وَيَتَوَضَّأُ ‏ ‏بِمَكُّوكٍ ‏","","",""],[13580,13580,"","আমরা শুনেছি, সে কি করেছে সে সম্পর্কে সে যা বলেছে সে তা নিয়ে আমি ভুলে গেছি... ...আর তার মা সেটা খেয়াল করবে না, হয়তো তুমি একটা বানাতে পারবে না। তার মানে ইটের সাথে সম্পর্কিত।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَعَثَ اللَّهُ عَزَّ وَجَلَّ نَبِيًّا إِلَّا أَنْذَرَ أُمَّتَهُ ‏ ‏الدَّجَّالَ ‏ ‏أَلَا إِنَّهُ الْأَعْوَرُ الْكَذَّابُ أَلَا إِنَّهُ أَعْوَرُ وَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَفَرَ ‏","","",""],[13581,13581,"","আমরা কথা বলেছিলাম, কিভাবে আমি সেই লোকদের শাসন করতে পারি যারা বলেছে, প্রভু, আমি যাব, তাদের বলে দিতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُمْ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏أَهْلُ الْكِتَابِ ‏ ‏إِذَا سَلَّمُوا عَلَيْنَا كَيْفَ نَرُدُّ عَلَيْهِمْ قَالَ ‏ ‏قُولُوا وَعَلَيْكُمْ ‏","","",""],[13582,13582,"","আমরা তোমার টাকা নিয়ে কথা বলেছিলাম ঈশ্বরকে বলতে, তারা তোমার মেহমান হবে যদি তুমি প্রার্থনার সময় নেকড়ের পশমটা তৈরি করো।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَوُّوا صُفُوفَكُمْ فَإِنَّ تَسْوِيَةَ الصُّفُوفِ مِنْ تَمَامِ الصَّلَاةِ ‏","","",""],[13583,13583,"","আমরা বলেছিলাম কিভাবে তারা ঈশ্বরকে জিজ্ঞেস করতো। কালোরা আর আমি তোমাকে নিয়ন্ত্রণ করতে পারছি না।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا يَبْسُطْ أَحَدُكُمْ ذِرَاعَيْهِ كَمَا يَبْسُطُ الْكَلْبُ ‏","","",""],[13584,13584,"","আমরা কথা বলেছিলাম কিভাবে আমরা আমাকে ঈশ্বরের কাছে পাঠানো লোকদের কথা বলতে চেষ্টা করেছি। তাহলে তো হতোই।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى رَجُلٍ يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏قَالَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ‏ ‏وَيْحَكَ ‏ ‏أَوْ وَيْلَكَ ‏ ‏ارْكَبْهَا ‏","","",""],[13585,13585,"","আমরা কথা বলেছি, আমরা কিভাবে তাদের নিয়ম করতে চেষ্টা করেছি, সে এটা বলতেই ছিল, তার প্রার্থনা শুনে আমি শপথ নিয়েছি, ঈশ্বর তাকে জয় করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي صَلَاتِهِ فَإِنَّهُ ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ عَزَّ وَجَلَّ فَلَا يَتْفُلَنَّ بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلْيَتْفُلْ عَنْ يَسَارِهِ تَحْتَ قَدَمِهِ ‏","","",""],[13586,13586,"","আমরা যেভাবে টাকাপয়সা নিয়ে পালিয়ে যাওয়ার চেষ্টা করেছিলাম, সেই বিষয়ে আমরা বলেছিলাম । তাকে মুক্ত করে দাও।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَزْعَةٌ ‏ ‏فَاسْتَعَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَسًا ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏يُقَالُ لَهُ مَنْدُوبٌ فَرَكِبَهُ وَقَالَ ‏ ‏مَا رَأَيْنَا مِنْ ‏ ‏فَزَعٍ ‏ ‏وَإِنْ وَجَدْنَاهُ ‏ ‏لَبَحْرًا ‏","","",""],[13587,13587,"","আমরা কথা বলেছিলাম আপনি বলতে যে আমি আপনাকে বলতে যাচ্ছি যে আমি আপনাকে শুনতে হবে আপনি শুনতে হবে যে আমি ভয় যে আমি মহান মহান মহান ভাববাদী তার কাছে প্রার্থনা করছি আপনার লোকেরা আপনাকে প্রার্থনা করে তাকে সান্ত্বনা দিয়েছে এবং তারা রসিকতা করার পরিকল্পনা করেছে । ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏ضَخْمًا لَا يَسْتَطِيعُ أَنْ يُصَلِّيَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي لَا أَسْتَطِيعُ أَنْ أُصَلِّيَ مَعَكَ فَصَنَعَ لَهُ طَعَامًا وَدَعَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِ ‏ ‏وَبَسَطُوا ‏ ‏لَهُ حَصِيرًا وَنَضَحُوهُ ‏ ‏فَصَلَّى عَلَيْهِ رَكْعَتَيْنِ فَقَالَ لَهُ رَجُلٌ مِنْ آلِ ‏ ‏الْجَارُودِ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى قَالَ مَا رَأَيْتُهُ صَلَّاهَا إِلَّا يَوْمَئِذٍ ‏","","",""],[13588,13588,"","ঈশ্বর তাকে এক রাত ধরে বাইরে গিয়ে মরতে দিয়ে তার শান্তি শেষ করেছেন ভয় পেয়ে গেল, তারপর সে তার মৃত্যুকে ছেড়ে দিবে যখন আমি ঈশ্বরের কাছে যেতে যাচ্ছি.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثُمَامَةُ بْنُ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَهُ أَصْحَابُهُ ذَاتَ لَيْلَةٍ فَخَرَجَ فَصَلَّى بِهِمْ فَخَفَّفَ ثُمَّ دَخَلَ بَيْتَهُ فَأَطَالَ ثُمَّ خَرَجَ فَصَلَّى بِهِمْ فَخَفَّفَ ثُمَّ دَخَلَ بَيْتَهُ فَأَطَالَ فَلَمَّا أَصْبَحَ قَالُوا يَا رَسُولَ اللَّهِ صَلَّيْتَ فَجَعَلْتَ تُطِيلُ إِذَا دَخَلْتَ وَتُخَفِّفُ إِذَا خَرَجْتَ قَالَ ‏ ‏مِنْ أَجْلِكُمْ فَعَلْتُ مَا فَعَلْتُ ‏","","",""],[13589,13589,"","আমি আমার বাবার সাথে কথা বলেছি, আমি তোমার টাকা ভুলে খুশি হতে চাই, যা ঈশ্বর তার সাথে করেছেন আর আমি এটা করতে চাই, সে ছিল বন্ধু।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبُ بْنُ الْحَبْحَابِ ‏ ‏وَعَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ ‏ ‏وَجَعَلَ عِتْقَهَا ‏ ‏صَدَاقَهَا ‏","","",""],[13590,13590,"","আমরা আমার বাবার সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ ‏ ‏وَجَعَلَ عِتْقَهَا ‏ ‏صَدَاقَهَا ‏","","",""],[13591,13591,"","আমরা ঈশ্বরের সাথে আমার বাবার সাথে কথা বলেছি, আমরা কথা বলেছি, ঈশ্বর তাঁর ছেলের ছেলেকে উদ্ধার করতে হবে, যারা বলেছে যে তিনি আমাদের খেতে বলছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَجَرَ ‏ ‏عَنْ الشُّرْبِ قَائِمًا ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏فَسَأَلْنَا ‏ ‏أَنَسًا ‏ ‏عَنْ الْأَكْلِ قَالَ ‏ ‏الْأَكْلُ أَشَدُّ ‏","","",""],[13592,13592,"","আমার সঙ্গে ঈশ্বর কথা বলেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنْتُ غُلَامًا ‏ ‏جَوَادًا ‏ ‏فَصِدْتُ أَرْنَبًا فَشَوَيْنَاهَا ‏ ‏فَأَرْسَلَ مَعِي ‏ ‏أَبُو طَلْحَةَ ‏ ‏بِعَجُزِهَا ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيْتُهُ بِهَا ‏","","",""],[13593,13593,"","আমরা আমার বাবার সঙ্গে ঈশ্বরের সঙ্গে কথা বলেছিলাম, কিন্তু তিনি অনেক দিন আগে আমাদের সঙ্গে কথা বলেছিলেন । আপনি তার কাছে এই কথা বলতে যাচ্ছেন যে, আপনি হয়তো তার জীবন নিয়ে চিন্তা করতে যাচ্ছেন । জিজ্ঞেস করো তুমি কে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُقَالُ لِلْكَافِرِ يَوْمَ الْقِيَامَةِ أَرَأَيْتَ لَوْ كَانَ لَكَ مِلْءُ الْأَرْضِ ذَهَبًا أَكُنْتَ ‏ ‏تَفْتَدِي ‏ ‏بِهِ فَيَقُولُ نَعَمْ قَالَ يُقَالُ لَهُ قَدْ سُئِلْتَ أَيْسَرَ مِنْ ذَلِكَ ‏","","",""],[13594,13594,"","আমরা ঈশ্বরের সাথে বাবার সাথে কথা বলেছি, কিন্তু আমি ঈশ্বরের সাথে কথা বলেছি। আপনার টাকা ভুলে যাওয়ার জন্য আমি তার কাছে প্রার্থনা করতে পছন্দ করি এবং তাকে জয় করতে বলে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَحَبَّ الثِّيَابِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَلْبَسَهَا ‏ ‏الْحِبَرَةُ ‏","","",""],[13595,13595,"","এরপর আমরা সেই টাকা ভুলে গিয়েছিলাম যে, ভাববাদী তার জন্য এসেছে এবং তার পালা করে চলেছেন । শহরের বুকে জিহ্বা, দশ নাম্বার নদী আমাকে বলেছে যে তিনজন মানুষ মারা যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏ثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَدُورُ عَلَى نِسَائِهِ فِي السَّاعَةِ الْوَاحِدَةِ مِنْ اللَّيْلِ وَالنَّهَارِ وَهُنَّ إِحْدَى عَشْرَةَ قَالَ قُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏هَلْ كَانَ يُطِيقُ ذَلِكَ قَالَ كُنَّا نَتَحَدَّثُ أَنَّهُ أُعْطِيَ قُوَّةَ ثَلَاثِينَ ‏","","",""],[13596,13596,"","আমরা ঈশ্বরের সঙ্গে কথা বলেছিলাম, আমার বাবা আমার সঙ্গে কথা বলেছিলেন কিন্তু আমি আমার প্রেমে কথা বলেছিলাম । তাকে হত্যা করতে ভয় পায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ تَمْرَةً فَقَالَ ‏ ‏لَوْلَا أَنِّي أَخَافُ أَنْ تَكُونَ ‏ ‏صَدَقَةً ‏ ‏لَأَكَلْتُهَا ‏","","",""],[13597,13597,"","আমরা ঈশ্বরের সাথে আমার বাবার সাথে কথা বলেছি, আর আমরা ঈশ্বরের সাথে কথা বলেছি, কিন্তু আমরা তার সাথে কথা বলেছি। আমরা ইতিমধ্যে তোমার টাকা নিয়ে ভুলে গেছি যে আমার ভাই তাকে এই কথা বলতে বলেছে। প্রত্যেক ছেলের একটা ফোন আছে, তুমি আমার মায়ের শক্তির মৃত্যু গুজবে ফোন দিয়েছ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ دَعْوَةً وَإِنِّي اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏","","",""],[13598,13598,"","আমি আমার নিজের দেশের একটা ছেলেকে খুঁজে পাওয়ার চেষ্টা করছিলাম বলে আমি কত কিছু ভেবেছিলাম, তা নিয়ে আমি আলোচনা করেছিলাম । তার সাথে আগুন ধরিয়ে দিয়ে বলে যে আমরা রক্তের বুকের উপর গামছা করে ফেলেছি, যদি তুমি নিজের বালিতে না থাকো, তার সকল গলা তার নিজের চোখে কখনোই তাকে কখনোই ঢুকতে দেবে না। ভন্ড না, আমি বলতে চাচ্ছি যে, যে কিনা খারাপ লোক আর তুমি বাইরে যাবে, খবর হচ্ছে যে তার সাথে কত বড় ধাক্কাটা হবে। তার সাথে থাকবে, সে লর্ডের সাথে গুলি করেছে আর বলেছে যে ঈশ্বর আমার কাছে এসেছেন, তুমি সেই সময় হবে ড্রাগন গার্লস বুলেটিন থেকে বেড়ে ওঠার সময়, আর এটা আমার বাবার বাবা না তার মা তার চোখের দিকে হাত রেখে বলল যে সে ঈশ্বরকে দেখে আর সে তা করতে চায় না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ أَحْمَدُ بْنُ جَعْفَرِ بْنِ حَمْدَانَ بْنِ مَالِكٍ الْقُطَيعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏زَيْدٍ يَعْنِي ابْنَ أَسْلَمَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏قَالَ ‏ ‏أَشْرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏فَلَقٍ ‏ ‏مِنْ ‏ ‏أَفْلَاقِ ‏ ‏الْحَرَّةِ ‏ ‏وَنَحْنُ مَعَهُ فَقَالَ ‏ ‏نِعْمَتِ الْأَرْضُ ‏ ‏الْمَدِينَةُ ‏ ‏إِذَا خَرَجَ ‏ ‏الدَّجَّالُ ‏ ‏عَلَى كُلِّ ‏ ‏نَقْبٍ ‏ ‏مِنْ ‏ ‏أَنْقَابِهَا ‏ ‏مَلَكٌ لَا يَدْخُلُهَا فَإِذَا كَانَ كَذَلِكَ رَجَفَتْ ‏ ‏الْمَدِينَةُ ‏ ‏بِأَهْلِهَا ثَلَاثَ رَجَفَاتٍ لَا يَبْقَى مُنَافِقٌ وَلَا مُنَافِقَةٌ إِلَّا خَرَجَ إِلَيْهِ وَأَكْثَرُ ‏ ‏يَعْنِي مَنْ يَخْرُجُ إِلَيْهِ النِّسَاءُ ‏ ‏وَذَلِكَ يَوْمُ التَّخْلِيصِ وَذَلِكَ يَوْمَ ‏ ‏تَنْفِي ‏ ‏الْمَدِينَةُ ‏ ‏الْخَبَثَ كَمَا يَنْفِي ‏ ‏الْكِيرُ ‏ ‏خَبَثَ الْحَدِيدِ يَكُونُ مَعَهُ سَبْعُونَ أَلْفًا مِنْ ‏ ‏الْيَهُودِ ‏ ‏عَلَى كُلِّ رَجُلٍ مِنْهُمْ ‏ ‏سَاجٌ ‏ ‏وَسَيْفٌ مُحَلًّى فَتُضْرَبُ رَقَبَتُهُ بِهَذَا الضَّرْبِ الَّذِي عِنْدَ مُجْتَمَعِ السُّيُولِ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا كَانَتْ ‏ ‏فِتْنَةٌ ‏ ‏وَلَا تَكُونُ حَتَّى تَقُومَ السَّاعَةُ أَكْبَرَ مِنْ ‏ ‏فِتْنَةِ ‏ ‏الدَّجَّالِ ‏ ‏وَلَا مِنْ نَبِيٍّ إِلَّا وَقَدْ حَذَّرَ أُمَّتَهُ وَلَأُخْبِرَنَّكُمْ بِشَيْءٍ مَا أَخْبَرَهُ نَبِيٌّ أُمَّتَهُ قَبْلِي ثُمَّ وَضَعَ يَدَهُ عَلَى عَيْنِهِ ثُمَّ قَالَ أَشْهَدُ أَنَّ اللَّهَ عَزَّ وَجَلَّ لَيْسَ بِأَعْوَرَ ‏","","",""],[13599,13599,"","আমরা রাজার সাথে আমার ভালবাসার কথা বলেছিলাম। আমি পাগল হয়ে যাওয়ার চেয়ে ভাল হব। কবি বলেছিলেন, তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন... ...এবং আপনার মাথা ও ফ্রেমের চেয়েও বেশি কিছু করবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ مِقْسَمٍ ‏ ‏قَالَ ‏ ‏سَأَلَ ‏ ‏الْحَسَنُ بْنُ مُحَمَّدٍ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏عَنْ الْغُسْلِ مِنْ الْجَنَابَةِ فَقَالَ تَبُلُّ الشَّعْرَ وَتَغْسِلُ الْبَشَرَةَ قَالَ فَكَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ قَالَ كَانَ ‏ ‏يَصُبُّ عَلَى رَأْسِهِ ثَلَاثًا قَالَ إِنَّ رَأْسِي كَثِيرُ الشَّعْرِ قَالَ كَانَ رَأْسُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرَ مِنْ رَأْسِكَ وَأَطْيَبَ ‏","","",""],[13600,13600,"","ঈশ্বর বলেছিলেন, আমরা ঈশ্বরের কাছে প্রার্থনা করেছি এবং এমন একজন ব্যক্তির মাধ্যমে আমরা ক্ষমা পাব, যিনি আমাদের ক্ষমা করবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏بَايَعْنَا نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏عَلَى أَنْ لَا ‏ ‏نَفِرَّ ‏","","",""]];
